import math
def srgb_to_lab(r,g,b):
    def lin(c):
        c/=255
        return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
    R,G,B=lin(r),lin(g),lin(b)
    X=R*0.4124+G*0.3576+B*0.1805
    Y=R*0.2126+G*0.7152+B*0.0722
    Z=R*0.0193+G*0.1192+B*0.9505
    def f(t):
        return t**(1/3) if t>0.008856 else 7.787*t+16/116
    fx,fy,fz=f(X/0.95047),f(Y/1.0),f(Z/1.08883)
    return (116*fy-16, 500*(fx-fy), 200*(fy-fz))
pal = {'black':(0,0,0),'maroon':(128,0,0),'green':(0,128,0),'olive':(128,128,0),'navy':(0,0,128),'purple':(128,0,128),'teal':(0,128,128),'silver':(192,192,192)}
def nearest(c, metric):
    best=None
    for n,p in pal.items():
        d=metric(c,p)
        if best is None or d<best[0]: best=(d,n)
    return best[1]
def lab76(c,p):
    a=srgb_to_lab(*c); b=srgb_to_lab(*p)
    return sum((x-y)**2 for x,y in zip(a,b))
def redmean(c,p):
    rm=(c[0]+p[0])/2
    dr,dg,db=c[0]-p[0],c[1]-p[1],c[2]-p[2]
    return (2+rm/256)*dr*dr+4*dg*dg+(2+(255-rm)/256)*db*db
def eucl(c,p): return sum((x-y)**2 for x,y in zip(c,p))
def lab_noL(c,p):
    a=srgb_to_lab(*c); b=srgb_to_lab(*p)
    return sum((x-y)**2 for x,y in zip(a[1:],b[1:]))
data = [((255,135,0),'maroon'),((255,136,0),'olive'),((192,105,0),'maroon'),((192,107,0),'olive'),((208,112,0),'maroon'),((230,113,0),'maroon'),((160,96,0),'olive'),((128,96,0),'olive'),((176,128,0),'olive'),((255,96,0),'maroon'),((192,64,0),'maroon'),((36,121,208),'teal'),((52,152,219),'teal'),((128,128,128),'silver'),((192,192,192),'silver'),((255,255,255),'silver'),((64,64,64),'black'),((0,255,128),'green'),((0,128,255),'navy'),((128,0,255),'navy'),((255,0,128),'purple'),((128,128,0),'olive'),((255,0,0),'maroon')]
