{"command":"mkdir -p /workspace/src && cat > /workspace/src/flags.go <<'EOF'
package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
)

// flagKind describes the value type of a command line flag.
type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindInt
	kindStrings
)

// flagDef is a single command line flag definition (pflag compatible subset).
type flagDef struct {
	name      string
	shorthand string
	kind      flagKind
	usage     string
	defValue  string // textual default used in help output

	boolVal    *bool
	stringVal  *string
	intVal     *int
	stringsVal *[]string

	changed bool
}

type flagSet struct {
	flags  []*flagDef
	byName map[string]*flagDef
	byChar map[string]*flagDef
	args   []string
}

func newFlagSet() *flagSet {
	return &flagSet{byName: map[string]*flagDef{}, byChar: map[string]*flagDef{}}
}

func (fs *flagSet) add(f *flagDef) {
	fs.flags = append(fs.flags, f)
	fs.byName[f.name] = f
	if f.shorthand != "" {
		fs.byChar[f.shorthand] = f
	}
}

func (fs *flagSet) boolVar(p *bool, name, short string, def bool, usage string) {
	*p = def
	fs.add(&flagDef{name: name, shorthand: short, kind: kindBool, usage: usage, boolVal: p, defValue: strconv.FormatBool(def)})
}

func (fs *flagSet) stringVar(p *string, name, short string, def string, usage string) {
	*p = def
	fs.add(&flagDef{name: name, shorthand: short, kind: kindString, usage: usage, stringVal: p, defValue: def})
}

func (fs *flagSet) intVar(p *int, name, short string, def int, usage string) {
	*p = def
	fs.add(&flagDef{name: name, shorthand: short, kind: kindInt, usage: usage, intVal: p, defValue: strconv.Itoa(def)})
}

func (fs *flagSet) stringsVar(p *[]string, name, short string, def []string, usage string) {
	*p = def
	fs.add(&flagDef{name: name, shorthand: short, kind: kindStrings, usage: usage, stringsVal: p, defValue: "[" + strings.Join(def, ",") + "]"})
}

func (f *flagDef) typeName() string {
	switch f.kind {
	case kindString:
		return "string"
	case kindInt:
		return "int"
	case kindStrings:
		return "strings"
	}
	return ""
}

func (f *flagDef) flagLabel() string {
	if f.shorthand != "" {
		return fmt.Sprintf("-%s, --%s", f.shorthand, f.name)
	}
	return "--" + f.name
}

func readAsCSV(val string) ([]string, error) {
	if val == "" {
		return []string{}, nil
	}
	r := csv.NewReader(strings.NewReader(val))
	rec, err := r.Read()
	if err == io.EOF {
		return []string{}, nil
	}
	return rec, err
}

func (f *flagDef) set(val string) error {
	switch f.kind {
	case kindBool:
		v, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", val, f.flagLabel(), err)
		}
		*f.boolVal = v
	case kindString:
		*f.stringVal = val
	case kindInt:
		v, err := strconv.ParseInt(val, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", val, f.flagLabel(), err)
		}
		*f.intVal = int(v)
	case kindStrings:
		vals, err := readAsCSV(val)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", val, f.flagLabel(), err)
		}
		if !f.changed {
			*f.stringsVal = vals
		} else {
			*f.stringsVal = append(*f.stringsVal, vals...)
		}
	}
	f.changed = true
	return nil
}

func (f *flagDef) defaultIsZero() bool {
	switch f.kind {
	case kindBool:
		return f.defValue == "false"
	case kindString:
		return f.defValue == ""
	case kindInt:
		return f.defValue == "0"
	case kindStrings:
		return f.defValue == "[]"
	}
	return true
}

// parse parses the arguments the way pflag does (interspersed flags allowed).
func (fs *flagSet) parse(args []string) error {
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.args = append(fs.args, s)
			continue
		}
		if s[1] == '-' {
			if len(s) == 2 { // "--" terminates the flags
				fs.args = append(fs.args, args...)
				break
			}
			var err error
			args, err = fs.parseLongArg(s, args)
			if err != nil {
				return err
			}
		} else {
			var err error
			args, err = fs.parseShortArg(s, args)
			if err != nil {
				return err
			}
		}
	}
	return nil
}

func (fs *flagSet) parseLongArg(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	split := strings.SplitN(name, "=", 2)
	name = split[0]
	flag, ok := fs.byName[name]
	if !ok {
		if name == "help" {
			return args, errHelp
		}
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	var value string
	if len(split) == 2 {
		value = split[1]
	} else if flag.kind == kindBool {
		value = "true"
	} else if len(args) > 0 {
		value = args[0]
		args = args[1:]
	} else {
		return args, fmt.Errorf("flag needs an argument: --%s", name)
	}
	if err := flag.set(value); err != nil {
		return args, err
	}
	return args, nil
}

func (fs *flagSet) parseShortArg(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	for len(shorthands) > 0 {
		var err error
		shorthands, args, err = fs.parseSingleShort(shorthands, args)
		if err != nil {
			return args, err
		}
	}
	return args, nil
}

func (fs *flagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	outShorts := shorthands[1:]
	c := shorthands[0]
	flag, ok := fs.byChar[string(c)]
	if !ok {
		if c == 'h' {
			return "", args, errHelp
		}
		return "", args, fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorthands)
	}
	var value string
	if len(shorthands) > 2 && shorthands[1] == '=' {
		value = shorthands[2:]
		outShorts = ""
	} else if flag.kind == kindBool {
		value = "true"
	} else if len(shorthands) > 1 {
		value = shorthands[1:]
		outShorts = ""
	} else if len(args) > 0 {
		value = args[0]
		args = args[1:]
	} else {
		return "", args, fmt.Errorf("flag needs an argument: %q in -%s", c, shorthands)
	}
	if err := flag.set(value); err != nil {
		return "", args, err
	}
	return outShorts, args, nil
}

// usages renders the flag usage block the way pflag does.
func (fs *flagSet) usages() string {
	flags := make([]*flagDef, len(fs.flags))
	copy(flags, fs.flags)
	sort.Slice(flags, func(i, j int) bool { return flags[i].name < flags[j].name })
	lines := []string{}
	maxlen := 0
	for _, f := range flags {
		var line string
		if f.shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.shorthand, f.name)
		} else {
			line = fmt.Sprintf("      --%s", f.name)
		}
		if t := f.typeName(); t != "" {
			line += " " + t
		}
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += f.usage
		if !f.defaultIsZero() {
			if f.kind == kindString {
				line += fmt.Sprintf(" (default %q)", f.defValue)
			} else {
				line += fmt.Sprintf(" (default %s)", f.defValue)
			}
		}
		lines = append(lines, line)
	}
	var b strings.Builder
	for _, line := range lines {
		sidx := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		fmt.Fprintln(&b, line[:sidx], spacing, line[sidx+1:])
	}
	return b.String()
}

type helpRequest struct{}

func (helpRequest) Error() string { return "help requested" }

var errHelp error = helpRequest{}
EOF
echo done"}

