}

func (fs *flagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	outShorts := shorthands[1:]
	c := shorthands[0]
	flag, ok := fs.byChar[string(c)]
	if !ok {
		if c == 'h' {
			return "", args, errHelp
		}
		return "", args, fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorthands)
	}
	var value string
	if len(shorthands) > 2 && shorthands[1] == '=' {
		value = shorthands[2:]
		outShorts = ""
	} else if flag.kind == kindBool {
		value = "true"
	} else if len(shorthands) > 1 {
		value = shorthands[1:]
		outShorts = ""
	} else if len(args) > 0 {
		value = args[0]
		args = args[1:]
	} else {
		return "", args, fmt.Errorf("flag needs an argument: %q in -%s", c, shorthands)
	}
	if err := flag.set(value); err != nil {
		return "", args, err
	}
	return outShorts, args, nil
}

// usages renders the flag usage block the way pflag does.
func (fs *flagSet) usages() string {
	flags := make([]*flagDef, len(fs.flags))
	copy(flags, fs.flags)
	sort.Slice(flags, func(i, j int) bool { return flags[i].name < flags[j].name })
	lines := []string{}
	maxlen := 0
	for _, f := range flags {
		var line string
		if f.shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.shorthand, f.name)
		} else {
			line = fmt.Sprintf("      --%s", f.name)
		}
		if t := f.typeName(); t != "" {
			line += " " + t
		}
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += f.usage
		if !f.defaultIsZero() {
			if f.kind == kindString {
				line += fmt.Sprintf(" (default %q)", f.defValue)
			} else {
				line += fmt.Sprintf(" (default %s)", f.defValue)
			}
		}
		lines = append(lines, line)
	}
	var b strings.Builder
	for _, line := range lines {
		sidx := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		fmt.Fprintln(&b, line[:sidx], spacing, line[sidx+1:])
	}
	return b.String()
}

