// ---- minimal YAML reader (block style maps, lists and scalars) ----

type yamlNode struct {
	kind   int // 0 scalar, 1 map, 2 list
	scalar string
	quoted bool
	keys   []string
	m      map[string]*yamlNode
	list   []*yamlNode
}

type yamlLine struct {
	indent int
	text   string
}

func yamlUnquote(s string) (string, bool) {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'"), true
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if u, err := strconv.Unquote(s); err == nil {
			return u, true
		}
		return s[1 : len(s)-1], true
	}
	// strip trailing comments
	if i := strings.Index(s, " #"); i >= 0 {
		s = strings.TrimSpace(s[:i])
	}
	return s, false
}

func parseYAML(data string) (*yamlNode, error) {
	var lines []yamlLine
	for _, raw := range strings.Split(data, "\n") {
		raw = strings.TrimRight(raw, "\r")
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || trimmed == "---" {
			continue
		}
		indent := 0
		for indent < len(raw) && raw[indent] == ' ' {
			indent++
		}
		lines = append(lines, yamlLine{indent: indent, text: trimmed})
	}
	pos := 0
	node, err := parseYAMLBlock(lines, &pos, -1)
	if err != nil {
		return nil, err
	}
	if pos < len(lines) {
		return nil, fmt.Errorf("yaml: line %d: did not find expected key", pos+1)
	}
	return node, nil
}

func parseYAMLBlock(lines []yamlLine, pos *int, parentIndent int) (*yamlNode, error) {
	if *pos >= len(lines) {
		return &yamlNode{kind: 0}, nil
	}
	indent := lines[*pos].indent
	if indent <= parentIndent {
		return &yamlNode{kind: 0}, nil
	}
	first := lines[*pos].text
	if strings.HasPrefix(first, "- ") || first == "-" {
		node := &yamlNode{kind: 2}
		for *pos < len(lines) && lines[*pos].indent == indent && (strings.HasPrefix(lines[*pos].text, "- ") || lines[*pos].text == "-") {
			item := strings.TrimSpace(strings.TrimPrefix(lines[*pos].text, "-"))
			*pos++
			if item == "" {
				child, err := parseYAMLBlock(lines, pos, indent)
				if err != nil {
					return nil, err
				}
				node.list = append(node.list, child)
				continue
			}
			if isYAMLKey(item) {
				// inline map inside list: treat as a map by re-injecting
				k, v := splitYAMLKey(item)
				child := &yamlNode{kind: 1, m: map[string]*yamlNode{}}
				if v == "" {
					sub, err := parseYAMLBlock(lines, pos, indent)
					if err != nil {
						return nil, err
					}
					child.m[k] = sub
				} else {
					s, q := yamlUnquote(v)
					child.m[k] = &yamlNode{scalar: s, quoted: q}
				}
				child.keys = append(child.keys, k)
				node.list = append(node.list, child)
				continue
			}
			s, q := yamlUnquote(item)
			node.list = append(node.list, &yamlNode{scalar: s, quoted: q})
		}
		return node, nil
	}
	if first == "[]" {
		*pos++
		return &yamlNode{kind: 2}, nil
	}
	if !isYAMLKey(first) {
		s, q := yamlUnquote(first)
		*pos++
		return &yamlNode{scalar: s, quoted: q}, nil
	}
	node := &yamlNode{kind: 1, m: map[string]*yamlNode{}}
	for *pos < len(lines) && lines[*pos].indent == indent {
		text := lines[*pos].text
		if !isYAMLKey(text) {
			return nil, fmt.Errorf("yaml: line %d: could not find expected ':'", *pos+1)
		}
		k, v := splitYAMLKey(text)
		*pos++
		if v == "" {
			child, err := parseYAMLBlock(lines, pos, indent)
			if err != nil {
				return nil, err
			}
			node.m[k] = child
		} else if v == "[]" {
			node.m[k] = &yamlNode{kind: 2}
		} else if strings.HasPrefix(v, "[") && strings.HasSuffix(v, "]") {
			ln := &yamlNode{kind: 2}
			for _, it := range strings.Split(v[1:len(v)-1], ",") {
				it = strings.TrimSpace(it)
				if it == "" {
					continue
				}
				s, q := yamlUnquote(it)
				ln.list = append(ln.list, &yamlNode{scalar: s, quoted: q})
			}
			node.m[k] = ln
		} else {
			s, q := yamlUnquote(v)
			node.m[k] = &yamlNode{scalar: s, quoted: q}
		}
		node.keys = append(node.keys, k)
	}
	return node, nil
}

func isYAMLKey(s string) bool {
	if strings.HasPrefix(s, "'") || strings.HasPrefix(s, "\"") {
		return false
	}
	i := strings.Index(s, ":")
	if i <= 0 {
		return false
	}
	return i == len(s)-1 || s[i+1] == ' '
}

func splitYAMLKey(s string) (string, string) {
	i := strings.Index(s, ":")
	return strings.TrimSpace(s[:i]), strings.TrimSpace(s[i+1:])
}

func (n *yamlNode) get(key string) *yamlNode {
	if n == nil || n.kind != 1 {
		return nil
	}
	return n.m[key]
}

func (n *yamlNode) str(target *string) {
	if n != nil && n.kind == 0 {
		*target = n.scalar
	}
}

func (n *yamlNode) boolean(target *bool) {
	if n != nil && n.kind == 0 {
		switch strings.ToLower(n.scalar) {
		case "true", "yes", "on", "y":
			*target = true
		case "false", "no", "off", "n":
			*target = false
		}
	}
}

func (n *yamlNode) integer(target *int) {
	if n != nil && n.kind == 0 {
		if v, err := strconv.Atoi(n.scalar); err == nil {
			*target = v
		}
	}
}

func (n *yamlNode) strList(target *[]string) {
	if n == nil {
		return
	}
	if n.kind == 2 {
		out := []string{}
		for _, it := range n.list {
			if it.kind == 0 {
				out = append(out, it.scalar)
			}
		}
		*target = out
	} else if n.kind == 0 && n.scalar == "" {
		*target = []string{}
	}
}

// applyConfig loads the values from a parsed YAML document into the flags.
func applyConfig(root *yamlNode, f *Flags) {
	if root == nil || root.kind != 1 {
		return
	}
	if st := root.get("style"); st != nil {
		if ft := st.get("footer"); ft != nil {
			ft.get("text-color").str(&f.Style.Footer.TextColor)
			ft.get("background-color").str(&f.Style.Footer.BackgroundColor)
			ft.get("number-color").str(&f.Style.Footer.NumberColor)
		}
		if sr := st.get("selected-row"); sr != nil {
			sr.get("text-color").str(&f.Style.SelectedRow.TextColor)
			sr.get("background-color").str(&f.Style.SelectedRow.BackgroundColor)
		}
		if rr := st.get("result-row"); rr != nil {
			rr.get("number-color").str(&f.Style.ResultRow.NumberColor)
			rr.get("directory-color").str(&f.Style.ResultRow.DirectoryColor)
		}
		if hd := st.get("header"); hd != nil {
			hd.get("text-color").str(&f.Style.Header.TextColor)
			hd.get("background-color").str(&f.Style.Header.BackgroundColor)
			hd.get("hidden").boolean(&f.Style.Header.Hidden)
		}
		if pm := st.get("progress-modal"); pm != nil {
			pm.get("current-item-path-max-len").integer(&f.Style.ProgressModal.CurrentItemNameMaxLen)
		}
		st.get("use-old-size-bar").boolean(&f.Style.UseOldSizeBar)
	}
	if so := root.get("sorting"); so != nil {
		so.get("by").str(&f.Sorting.By)
		so.get("order").str(&f.Sorting.Order)
	}
	root.get("log-file").str(&f.LogFile)
	root.get("input-file").str(&f.InputFile)
	root.get("output-file").str(&f.OutputFile)
	root.get("ignore-from-file").str(&f.IgnoreFromFile)
	root.get("ignore-dirs").strList(&f.IgnoreDirs)
	root.get("ignore-dir-patterns").strList(&f.IgnoreDirPatterns)
	root.get("type").strList(&f.TypeFilter)
	root.get("exclude-type").strList(&f.ExcludeTypeFilter)
	root.get("max-cores").integer(&f.MaxCores)
	root.get("top").integer(&f.Top)
	root.get("depth").integer(&f.Depth)
	root.get("sequential-scanning").boolean(&f.SequentialScanning)
	root.get("show-disks").boolean(&f.ShowDisks)
	root.get("show-apparent-size").boolean(&f.ShowApparentSize)
	root.get("show-relative-size").boolean(&f.ShowRelativeSize)
	root.get("show-annexed-size").boolean(&f.ShowAnnexedSize)
	root.get("show-item-count").boolean(&f.ShowItemCount)
	root.get("show-mtime").boolean(&f.ShowMTime)
