	root.get("non-interactive").boolean(&f.NonInteractive)
	root.get("no-progress").boolean(&f.NoProgress)
	root.get("no-unicode").boolean(&f.NoUnicode)
	root.get("no-cross").boolean(&f.NoCross)
	root.get("no-hidden").boolean(&f.NoHidden)
	root.get("no-delete").boolean(&f.NoDelete)
	root.get("no-spawn-shell").boolean(&f.NoSpawnShell)
	root.get("follow-symlinks").boolean(&f.FollowSymlinks)
	root.get("profiling").boolean(&f.Profiling)
	root.get("read-from-storage").boolean(&f.ReadFromStorage)
	root.get("db").str(&f.DbPath)
	root.get("summarize").boolean(&f.Summarize)
	root.get("use-si-prefix").boolean(&f.UseSIPrefix)
	root.get("no-prefix").boolean(&f.NoPrefix)
	root.get("show-in-kib").boolean(&f.ShowInKiB)
	root.get("reverse-sort").boolean(&f.ReverseSort)
	root.get("change-cwd").boolean(&f.ChangeCwd)
	root.get("delete-in-background").boolean(&f.DeleteInBackground)
	root.get("delete-in-parallel").boolean(&f.DeleteInParallel)
	root.get("since").str(&f.Since)
	root.get("until").str(&f.Until)
	root.get("max-age").str(&f.MaxAge)
	root.get("min-age").str(&f.MinAge)
	root.get("archive-browsing").boolean(&f.ArchiveBrowsing)
	root.get("collapse-path").boolean(&f.CollapsePath)
}

// readConfigFile reads the config file and returns an error if it can't be read.
func readConfigFile(path string, f *Flags) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	root, err := parseYAML(string(data))
	if err != nil {
		return err
	}
	applyConfig(root, f)
	return nil
}
