	// strings starting with '#' or containing special chars are single quoted
	needs := strings.HasPrefix(s, "#") || strings.ContainsAny(s, ":{}[],&*!|>'\"%@`") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") ||
		s == "true" || s == "false" || s == "null" || s == "~" || s == "yes" || s == "no"
	if !needs {
		if _, err := strconv.ParseFloat(s, 64); err == nil {
			needs = true
		}
	}
	if needs {
		return "'" + strings.ReplaceAll(s, "'", "''") + "'"
	}
	return s
}

func yamlList(items []string, indent string) string {
	if len(items) == 0 {
		return " []\n"
	}
	var b strings.Builder
	b.WriteString("\n")
	for _, it := range items {
		b.WriteString(indent + "- " + yamlQuote(it) + "\n")
	}
	return b.String()
}

