// readConfigFile reads the config file and returns an error if it can't be read.
func readConfigFile(path string, f *Flags) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	root, err := parseYAML(string(data))
	if err != nil {
		return err
	}
	applyConfig(root, f)
	return nil
}
