func newAnalyzer(f *Flags, ignoreDirs map[string]bool, ignoreRe *regexp.Regexp, tf *timeFilter) *Analyzer {
	a := &Analyzer{flags: f, ignoreDirs: ignoreDirs, ignoreRe: ignoreRe, timeFilter: tf, progress: &Progress{}}
	if len(f.TypeFilter) > 0 {
		a.typeFilter = map[string]bool{}
		for _, t := range f.TypeFilter {
