			} else {
				acc += "/" + part
			}
			d, ok := dirs[acc]
			if !ok {
				d = &Item{Name: part, Flag: 'Z', IsDir: true, Size: dirOwnSize, Usage: dirOwnSize, Mtime: file.Mtime, ownMtime: file.Mtime}
