			base = name[i+1:]
		}
		d := getDir(dirPart)
		size := int64(f.UncompressedSize64)
		d.addFile(&Item{Name: base, Flag: ' ', Size: size, Usage: size, Mtime: f.Modified})
	}
	return root
}

// annexedSize parses the size from a git-annex key (e.g. SHA256E-s12345--hash).
func annexedSize(target string) (int64, bool) {
	if !strings.Contains(target, "annex/objects") {
		return 0, false
	}
	base := filepath.Base(target)
	i := strings.Index(base, "-s")
	if i < 0 {
		return 0, false
	}
	rest := base[i+2:]
	j := 0
	for j < len(rest) && rest[j] >= '0' && rest[j] <= '9' {
		j++
	}
	if j == 0 {
		return 0, false
	}
	v, err := strconv.ParseInt(rest[:j], 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

