	sortChildren(root)
	atomic.StoreInt32(&a.progress.done, 1)
	return root
}

type dirTask struct {
	path string
	dir  *Item
}

// runQueue processes directory tasks with a bounded number of workers.
func (a *Analyzer) runQueue(first *dirTask) {
	workers := a.flags.MaxCores
	if workers < 1 || a.seqMode {
		workers = 1
	}
	var mu sync.Mutex
	cond := sync.NewCond(&mu)
	queue := []*dirTask{first}
	pending := 1
	done := false

	push := func(t *dirTask) {
		mu.Lock()
		queue = append(queue, t)
		pending++
		cond.Broadcast()
		mu.Unlock()
	}
	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				mu.Lock()
				for len(queue) == 0 && !done {
					cond.Wait()
				}
				if done && len(queue) == 0 {
					mu.Unlock()
					return
				}
				t := queue[0]
				queue = queue[1:]
				mu.Unlock()
				a.processDir(t, push)
				mu.Lock()
				pending--
				if pending == 0 {
					done = true
					cond.Broadcast()
				}
