var binaryUnits = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
var siUnits = []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}

// sizeParts splits a size into the number and unit the way gdu does.
func sizeParts(size int64, si, kib, noPrefix bool) (string, string) {
	if noPrefix {
		return strconv.FormatInt(size, 10), ""
	}
	fsize := float64(size)
	if kib {
		if si {
			return fmt.Sprintf("%.1f", fsize/1000), "kB"
		}
		return fmt.Sprintf("%.1f", fsize/1024), "KiB"
	}
	base := 1024.0
	units := binaryUnits
	if si {
		base = 1000.0
		units = siUnits
	}
	asize := math.Abs(fsize)
	for i := len(units) - 1; i >= 1; i-- {
		if asize >= math.Pow(base, float64(i)) {
			return fmt.Sprintf("%.1f", fsize/math.Pow(base, float64(i))), units[i]
		}
	}
	return strconv.FormatInt(size, 10), "B"
}

// formatSizePlain formats the size as "num unit".
func formatSizePlain(size int64, si, kib, noPrefix bool) string {
	num, unit := sizeParts(size, si, kib, noPrefix)
	if unit == "" {
		return num
	}
	return num + " " + unit
}

// thousands formats an integer with comma separators.
func thousands(n int64) string {
	s := strconv.FormatInt(n, 10)
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	var b strings.Builder
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(c)
	}
	if neg {
		return "-" + b.String()
	}
	return b.String()
}
