	}
	return s
}

func (ui *StdoutUI) red(s string) string {
	if ui.useColor {
		return ansiRed + s + ansiReset
	}
	return s
}

func (ui *StdoutUI) blue(s string) string {
	if ui.useColor {
		return ansiBlue + s + ansiReset
	}
	return s
}

// formatSize formats the size with the number highlighted.
func (ui *StdoutUI) formatSize(size int64) string {
	num, unit := sizeParts(size, ui.flags.UseSIPrefix, ui.flags.ShowInKiB, ui.flags.NoPrefix)
	s := ui.orange(num)
	if unit != "" {
		s += " " + unit
	}
	if ui.useColor {
		return fmt.Sprintf("%20s", s)
	}
	return fmt.Sprintf("%9s", s)
}

func (ui *StdoutUI) clearLine() {
	fmt.Fprint(ui.out, "\r"+strings.Repeat(" ", 100)+"\r")
}

func (ui *StdoutUI) nextFrame() string {
	f := spinnerFrames[ui.spin%len(spinnerFrames)]
	ui.spin++
	return f
}

// runProgress prints the scanning progress until stop is closed.
func (ui *StdoutUI) runProgress(p *Progress, stop <-chan struct{}, wg *sync.WaitGroup) {
	defer wg.Done()
	ticker := time.NewTicker(250 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-stop:
			ui.mu.Lock()
			ui.clearLine()
			ui.mu.Unlock()
			return
		case <-ticker.C:
			items, size, _ := p.snapshot()
			ui.mu.Lock()
			ui.clearLine()
			fmt.Fprintf(ui.out, "\r %s ", ui.nextFrame())
			fmt.Fprintf(ui.out, "Scanning... Total items: %s size: %s", ui.red(thousands(items)), formatSizeTrim(ui, size))
			ui.mu.Unlock()
		}
	}
}

func formatSizeTrim(ui *StdoutUI, size int64) string {
	num, unit := sizeParts(size, ui.flags.UseSIPrefix, ui.flags.ShowInKiB, ui.flags.NoPrefix)
	s := ui.orange(num)
	if unit != "" {
		s += " " + unit
	}
	return s
}

func (ui *StdoutUI) showCalculating() {
	if !ui.progress {
		return
	}
	ui.clearLine()
	fmt.Fprintf(ui.out, "\r %s Calculating disk usage...", ui.nextFrame())
}

func (ui *StdoutUI) hideCalculating() {
	if !ui.progress {
		return
	}
	ui.clearLine()
}

func (ui *StdoutUI) itemName(it *Item) string {
	if it.IsDir {
		return ui.blue("/" + it.Name)
	}
	return it.Name
}

// sortItems sorts by usage (and name) in ascending order, reversed unless reverse is set.
func sortItemsByUsage(items []*Item, reverse bool) {
	sort.SliceStable(items, func(i, j int) bool {
		a, b := items[i], items[j]
		if a.Usage != b.Usage {
			return a.Usage < b.Usage
		}
		return a.Name < b.Name
	})
	if !reverse {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}
}

func (ui *StdoutUI) sizeOf(it *Item) int64 {
	if ui.flags.ShowApparentSize {
		return it.Size
	}
	return it.Usage
}

// printDir prints the content of the analyzed directory.
func (ui *StdoutUI) printDir(dir *Item) {
	items := make([]*Item, len(dir.Files))
	copy(items, dir.Files)
	sortItemsByUsage(items, ui.flags.ReverseSort)
	var b strings.Builder
	for _, it := range items {
		fmt.Fprintf(&b, "%c %s %s\n", it.Flag, ui.formatSize(ui.sizeOf(it)), ui.itemName(it))
	}
	fmt.Fprint(ui.out, b.String())
}

// printSummary prints the total size of the directory.
func (ui *StdoutUI) printSummary(dir *Item) {
	fmt.Fprintf(ui.out, "%s %s\n", ui.formatSize(ui.sizeOf(dir)), dir.Name)
}

// printDepth prints the tree up to the given depth with full paths.
func (ui *StdoutUI) printDepth(dir *Item, depth int) {
	var b strings.Builder
	fmt.Fprintf(&b, "%s %s\n", ui.formatSize(ui.sizeOf(dir)), ui.blue(dir.Path()))
	ui.printDepthLevel(&b, dir, depth, 1)
	fmt.Fprint(ui.out, b.String())
}

func (ui *StdoutUI) printDepthLevel(b *strings.Builder, dir *Item, maxDepth, cur int) {
	if cur > maxDepth {
		return
	}
	items := make([]*Item, len(dir.Files))
	copy(items, dir.Files)
	sortItemsByUsage(items, ui.flags.ReverseSort)
	for _, it := range items {
		name := it.Path()
		if it.IsDir {
			name = ui.blue(name)
		}
		fmt.Fprintf(b, "%s %s\n", ui.formatSize(ui.sizeOf(it)), name)
		if it.IsDir {
			ui.printDepthLevel(b, it, maxDepth, cur+1)
		}
	}
}

// printTop prints the largest files.
func (ui *StdoutUI) printTop(dir *Item, n int) {
	var files []*Item
	collectFiles(dir, &files)
	sort.SliceStable(files, func(i, j int) bool {
		a, b := files[i], files[j]
		if a.Size != b.Size {
			return a.Size > b.Size
		}
		return a.Name > b.Name
	})
	if n < len(files) {
		files = files[:n]
	}
	var b strings.Builder
	for _, it := range files {
		fmt.Fprintf(&b, "%s %s\n", ui.formatSize(ui.sizeOf(it)), it.Path())
	}
	fmt.Fprint(ui.out, b.String())
}

func collectFiles(dir *Item, out *[]*Item) {
	for _, f := range dir.Files {
		if f.IsDir {
			collectFiles(f, out)
		} else {
			*out = append(*out, f)
		}
	}
}

// printDevices lists the mounted devices.
func (ui *StdoutUI) printDevices(devices []*Device) {
	maxLen := len("Device")
	for _, d := range devices {
		if len(d.Name) > maxLen {
			maxLen = len(d.Name)
		}
	}
	w := fmt.Sprint(maxLen)
	fmt.Fprintf(ui.out, "%"+w+"s %10s %10s %10s %5s %s\n", "Device", "Size", "Used", "Free", "Used%", "Mount point")
	for _, d := range devices {
		pct := "0%"
		if d.Size > 0 {
			pct = fmt.Sprintf("%d%%", int(float64(d.Size-d.Free)/float64(d.Size)*100))
		}
		fmt.Fprintf(ui.out, "%"+w+"s %s %s %s %5s %s\n", d.Name, ui.formatSize(d.Size), ui.formatSize(d.Size-d.Free), ui.formatSize(d.Free), ui.red(pct), d.MountPoint)
	}
}
EOF
