package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type timeFilter struct {
	since time.Time
	until time.Time
}

func (tf *timeFilter) allows(t time.Time) bool {
	if tf == nil {
		return true
	}
	if !tf.since.IsZero() && t.Before(tf.since) {
		return false
	}
	if !tf.until.IsZero() && t.After(tf.until) {
		return false
	}
	return true
}

var durationRe = regexp.MustCompile(`^(\d+)(mo|s|m|h|d|w|y)`)

// parseDurationSpec parses durations like 7d, 2h30m, 1y2mo.
func parseDurationSpec(spec string) (time.Duration, error) {
	s := strings.ToLower(strings.Join(strings.Fields(spec), ""))
	if s == "" {
		return 0, fmt.Errorf("invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", spec)
	}
	var total time.Duration
	rest := s
	for len(rest) > 0 {
		m := durationRe.FindStringSubmatch(rest)
		if m == nil {
			return 0, fmt.Errorf("invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", spec)
		}
		n, err := strconv.ParseInt(m[1], 10, 64)
		if err != nil {
			return 0, fmt.Errorf("invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", spec)
		}
		var unit time.Duration
		switch m[2] {
		case "s":
			unit = time.Second
		case "m":
			unit = time.Minute
		case "h":
			unit = time.Hour
		case "d":
			unit = 24 * time.Hour
		case "w":
			unit = 7 * 24 * time.Hour
		case "mo":
			unit = 30 * 24 * time.Hour
		case "y":
			unit = 365 * 24 * time.Hour
		}
		total += time.Duration(n) * unit
		rest = rest[len(m[0]):]
	}
	return total, nil
}

// parseTimeSpec parses RFC3339 timestamps or YYYY-MM-DD dates.
func parseTimeSpec(spec string, endOfDay bool) (time.Time, error) {
	if t, err := time.Parse(time.RFC3339, spec); err == nil {
		return t, nil
	}
	if t, err := time.ParseInLocation("2006-01-02", spec, time.Local); err == nil {
		if endOfDay {
			return t.AddDate(0, 0, 1).Add(-time.Nanosecond), nil
		}
		return t, nil
	}
	return time.Time{}, fmt.Errorf("invalid time value %q. Use RFC3339 timestamp or date only YYYY-MM-DD", spec)
}

// buildTimeFilter creates the filter from the flags, nil if none is set.
func buildTimeFilter(f *Flags) (*timeFilter, error) {
	if f.Since == "" && f.Until == "" && f.MaxAge == "" && f.MinAge == "" {
		return nil, nil
	}
	tf := &timeFilter{}
	now := time.Now()
	if f.Since != "" {
		t, err := parseTimeSpec(f.Since, false)
		if err != nil {
			return nil, fmt.Errorf("invalid --since value: %v", err)
		}
		tf.since = t
	}
	if f.Until != "" {
		t, err := parseTimeSpec(f.Until, true)
		if err != nil {
			return nil, fmt.Errorf("invalid --until value: %v", err)
		}
		tf.until = t
	}
	if f.MaxAge != "" {
		d, err := parseDurationSpec(f.MaxAge)
		if err != nil {
			return nil, fmt.Errorf("invalid --max-age value: %v", err)
		}
		t := now.Add(-d)
		if tf.since.IsZero() || t.After(tf.since) {
			tf.since = t
		}
	}
	if f.MinAge != "" {
		d, err := parseDurationSpec(f.MinAge)
		if err != nil {
			return nil, fmt.Errorf("invalid --min-age value: %v", err)
		}
		t := now.Add(-d)
		if tf.until.IsZero() || t.Before(tf.until) {
			tf.until = t
		}
	}
	return tf, nil
}
