func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// exportJSON writes the analysis in the ncdu compatible JSON format.
func exportJSON(w io.Writer, root *Item) error {
	bw := bufio.NewWriterSize(w, 1<<16)
	fmt.Fprintf(bw, "[1,2,{\"progname\":\"gdu\",\"progver\":\"%s\",\"timestamp\":%d},\n", versionString, time.Now().Unix())
	writeDirJSON(bw, root, true)
	bw.WriteString("]\n")
	return bw.Flush()
}

func writeDirJSON(w *bufio.Writer, dir *Item, isRoot bool) {
	name := dir.Name
	if isRoot {
		name = dir.Path()
	}
	w.WriteString("[{\"name\":" + jsonString(name) + ",\"mtime\":" + strconv.FormatInt(dir.Mtime.Unix(), 10) + "}")
	if len(dir.Files) == 0 {
		w.WriteString("\n")
	}
	for _, f := range dir.Files {
		w.WriteString(",\n")
		if f.IsDir {
			writeDirJSON(w, f, false)
		} else {
			writeFileJSON(w, f)
		}
	}
	w.WriteString("]")
}

func writeFileJSON(w *bufio.Writer, f *Item) {
	w.WriteString("{\"name\":" + jsonString(f.Name))
	if f.Size != 0 {
		w.WriteString(",\"asize\":" + strconv.FormatInt(f.Size, 10))
