// App drives the program according to the flags.
type App struct {
	flags      *Flags
	args       []string
	ignoreDirs map[string]bool
	ignoreRe   *regexp.Regexp
	timeFilter *timeFilter
}

func (a *App) prepareFilters() error {
	a.ignoreDirs = map[string]bool{}
	for _, d := range a.flags.IgnoreDirs {
		if !filepath.IsAbs(d) {
			if abs, err := filepath.Abs(d); err == nil {
				d = abs
			}
		}
		a.ignoreDirs[d] = true
	}
	logInfof("Ignoring dirs %s", strings.Join(sortedKeys(a.flags.IgnoreDirs, a.ignoreDirs), ", "))

	patterns := append([]string{}, a.flags.IgnoreDirPatterns...)
	if a.flags.IgnoreFromFile != "" {
		file, err := os.Open(a.flags.IgnoreFromFile)
		if err != nil {
			return err
		}
		sc := bufio.NewScanner(file)
		for sc.Scan() {
			patterns = append(patterns, sc.Text())
		}
		file.Close()
	}
	if len(patterns) > 0 {
		var parts []string
		for _, p := range patterns {
			if _, err := regexp.Compile(p); err != nil {
				return err
			}
			parts = append(parts, "(?:"+p+")")
		}
		re, err := regexp.Compile(strings.Join(parts, "|"))
		if err != nil {
			return err
		}
		a.ignoreRe = re
	}
	tf, err := buildTimeFilter(a.flags)
	if err != nil {
		return fmt.Errorf("invalid time filter: %w", err)
	}
	a.timeFilter = tf
	return nil
}

// sortedKeys returns the ignore dirs in their original order (made absolute).
func sortedKeys(orig []string, set map[string]bool) []string {
	out := make([]string, 0, len(orig))
	for _, d := range orig {
		if !filepath.IsAbs(d) {
			if abs, err := filepath.Abs(d); err == nil {
				d = abs
			}
		}
		out = append(out, d)
	}
	return out
}

func (a *App) scanPath() string {
	p := "."
	if len(a.args) > 0 {
		p = a.args[0]
	}
	abs, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return abs
}

func (a *App) run() error {
	f := a.flags
	if f.Profiling {
		startProfiling()
	}
	stdoutTTY := isTerminal(os.Stdout.Fd())
	if f.OutputFile != "" || f.NonInteractive || !stdoutTTY {
		return a.runStdout(stdoutTTY)
	}
	return a.runTUI()
}

func (a *App) newAnalyzer() *Analyzer {
	return newAnalyzer(a.flags, a.ignoreDirs, a.ignoreRe, a.timeFilter)
}

func (a *App) runStdout(tty bool) error {
	f := a.flags
	useColor := tty && !f.NoColor
	showProgress := tty && !f.NoProgress
	ui := newStdoutUI(f, useColor, showProgress)

	if f.InputFile != "" {
		if f.OutputFile != "" {
			return fmt.Errorf("reading analysis: %s", "reading analysis is not possible while exporting")
		}
		file, err := os.Open(f.InputFile)
		if err != nil {
			return fmt.Errorf("opening input file: %w", err)
		}
		root, err := importJSON(file)
		file.Close()
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
		updateStats(root, map[uint64]bool{})
		if f.Summarize {
			ui.printSummary(root)
		} else {
			ui.printDir(root)
		}
		return nil
	}

	if f.ShowDisks && f.OutputFile == "" {
		devices, err := getDevices()
		if err != nil {
			return fmt.Errorf("loading mount points: %w", err)
		}
		ui.printDevices(devices)
		return nil
	}

	if err := a.prepareFilters(); err != nil {
		return err
	}
