	if f.ReadFromStorage && f.DbPath != "" {
		r, err := loadStorage(f.DbPath)
		if err != nil {
			return err
		}
		root = r
	} else {
		logInfof("Analyzing path: %s", path)
		an := a.newAnalyzer()
		var wg sync.WaitGroup
		stop := make(chan struct{})
		if showProgress {
			wg.Add(1)
			go ui.runProgress(an.progress, stop, &wg)
		}
		root = an.Analyze(path)
		close(stop)
		wg.Wait()
	}

	if f.OutputFile != "" {
		updateStats(root, map[uint64]bool{})
		err := exportJSON(out, root)
		closeOut()
		if err != nil {
			return fmt.Errorf("writing output file: %w", err)
		}
		return nil
	}

