	updateStats(root, map[uint64]bool{})
	if f.DbPath != "" && !f.ReadFromStorage {
		dedupStoredLinks(root, map[uint64]bool{})
		if err := saveStorage(f.DbPath, root); err != nil {
			return err
		}
	}
	ui.hideCalculating()

	switch {
	case f.Top > 0:
		ui.printTop(root, f.Top)
	case f.Depth > 0:
		ui.printDepth(root, f.Depth)
	case f.Summarize:
		ui.printSummary(root)
	default:
		ui.printDir(root)
	}
