package main

import (
	"fmt"
	"net/http"
	_ "net/http/pprof"
	"os"
	"path/filepath"
	"strings"
)

// storageFile returns the file used to persist the analysis for the given db path.
func storageFile(dbPath string) (string, bool) {
	if strings.HasSuffix(dbPath, ".badger") {
		return filepath.Join(dbPath, "gdu.json"), true
	}
	return dbPath, false
}

// saveStorage persists the analysis tree.
func saveStorage(dbPath string, root *Item) error {
	file, isDir := storageFile(dbPath)
	if isDir {
		if err := os.MkdirAll(dbPath, 0755); err != nil {
			return fmt.Errorf("opening database: %w", err)
		}
	}
	f, err := os.OpenFile(file, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil {
		return fmt.Errorf("opening database: %w", err)
	}
	defer f.Close()
	return exportJSON(f, root)
}

// loadStorage reads a previously stored analysis.
func loadStorage(dbPath string) (*Item, error) {
	file, _ := storageFile(dbPath)
	f, err := os.Open(file)
	if err != nil {
		return nil, fmt.Errorf("opening database: %w", err)
	}
	defer f.Close()
	root, err := importJSON(f)
	if err != nil {
		return nil, fmt.Errorf("reading database: %w", err)
	}
	return root, nil
}

// dedupStoredLinks mimics the storage backend behaviour: only the first hard link keeps its size.
func dedupStoredLinks(dir *Item, seen map[uint64]bool) {
	for _, f := range dir.Files {
		if f.IsDir {
			dedupStoredLinks(f, seen)
			continue
		}
		if f.Mli == 0 {
			continue
		}
		if seen[f.Mli] {
