func rgb(v int) Color { return Color{colorRGB, v} }

var colorNames = map[string]int{
	"black": 0, "maroon": 1, "green": 2, "olive": 3, "navy": 4, "purple": 5, "teal": 6, "silver": 7,
	"gray": 8, "grey": 8, "red": 9, "lime": 10, "yellow": 11, "blue": 12, "fuchsia": 13, "aqua": 14, "white": 15,
	"orange": -0xffa500, "darkblue": -0x00008b, "darkred": -0x8b0000, "darkgreen": -0x006400, "cyan": 14, "magenta": 13,
	"lightgray": -0xd3d3d3, "lightgrey": -0xd3d3d3, "darkgray": -0xa9a9a9, "darkgrey": -0xa9a9a9, "pink": -0xffc0cb,
	"brown": -0xa52a2a, "gold": -0xffd700, "violet": -0xee82ee, "indigo": -0x4b0082,
}

// parseColor parses "#rrggbb" or a color name; the empty string yields the fallback.
func parseColor(s string, fallback Color) Color {
	s = strings.TrimSpace(s)
	if s == "" {
		return fallback
	}
	if strings.HasPrefix(s, "#") && len(s) == 7 {
		var v int
		if _, err := fmt.Sscanf(s[1:], "%06x", &v); err == nil {
			return rgb(v)
		}
		return fallback
	}
	if v, ok := colorNames[strings.ToLower(s)]; ok {
		if v < 0 {
			return rgb(-v)
		}
		return Color{colorNamed, v}
	}
	return fallback
}

var paletteRGB [256]int

func init() {
	base := []int{0x000000, 0x800000, 0x008000, 0x808000, 0x000080, 0x800080, 0x008080, 0xc0c0c0,
		0x808080, 0xff0000, 0x00ff00, 0xffff00, 0x0000ff, 0xff00ff, 0x00ffff, 0xffffff}
	copy(paletteRGB[:], base)
	levels := []int{0, 95, 135, 175, 215, 255}
	i := 16
	for _, r := range levels {
		for _, g := range levels {
			for _, b := range levels {
				paletteRGB[i] = r<<16 | g<<8 | b
				i++
			}
		}
	}
	for j := 0; j < 24; j++ {
		v := 8 + 10*j
		paletteRGB[i] = v<<16 | v<<8 | v
		i++
	}
}

func rgbToLab(c int) (float64, float64, float64) {
	lin := func(v int) float64 {
		f := float64(v) / 255
		if f <= 0.04045 {
			return f / 12.92
		}
		return math.Pow((f+0.055)/1.055, 2.4)
	}
	r, g, b := lin(c>>16&0xff), lin(c>>8&0xff), lin(c&0xff)
	x := r*0.4124 + g*0.3576 + b*0.1805
	y := r*0.2126 + g*0.7152 + b*0.0722
	z := r*0.0193 + g*0.1192 + b*0.9505
	f := func(t float64) float64 {
		if t > 0.008856 {
			return math.Cbrt(t)
		}
		return 7.787*t + 16.0/116.0
	}
	fx, fy, fz := f(x/0.95047), f(y/1.0), f(z/1.08883)
	return 116*fy - 16, 500 * (fx - fy), 200 * (fy - fz)
}

var nearestCache = map[int]int{}

// nearestPalette finds the perceptually closest palette entry among the first n colors.
func nearestPalette(c int, n int) int {
	key := c<<9 | n
	if v, ok := nearestCache[key]; ok {
		return v
	}
	l1, a1, b1 := rgbToLab(c)
	best, bestD := 0, math.MaxFloat64
	for i := 0; i < n; i++ {
		l2, a2, b2 := rgbToLab(paletteRGB[i])
		d := (l1-l2)*(l1-l2) + (a1-a2)*(a1-a2) + (b1-b2)*(b1-b2)
		if d < bestD {
			best, bestD = i, d
		}
	}
	nearestCache[key] = best
	return best
}

// Style is the visual style of a screen cell.
type Style struct {
	fg, bg Color
	bold   bool
}

// ---------- screen ----------

type Cell struct {
	ch    string
	width int
	style Style
}

type Terminal struct {
	w, h      int
	cells     []Cell
	colors    int // 8, 256 or 1<<24
	oldTermio syscall.Termios
	rawSet    bool
	in        *os.File
	out       *os.File
	keys      chan Key
	resize    chan struct{}
	stopInput chan struct{}
	buf       []byte
}

func terminalColors() int {
	term := os.Getenv("TERM")
	ct := os.Getenv("COLORTERM")
	if ct == "truecolor" || ct == "24bit" || strings.Contains(term, "truecolor") || strings.Contains(term, "direct") {
		return 1 << 24
	}
	if strings.Contains(term, "256color") || strings.Contains(term, "256colour") {
		return 256
	}
	switch {
	case strings.HasPrefix(term, "xterm"), strings.HasPrefix(term, "screen"), strings.HasPrefix(term, "tmux"),
		strings.HasPrefix(term, "rxvt"), strings.HasPrefix(term, "linux"), strings.HasPrefix(term, "vt100"),
		strings.HasPrefix(term, "ansi"), strings.HasPrefix(term, "konsole"), strings.HasPrefix(term, "alacritty"),
		strings.HasPrefix(term, "kitty"), strings.HasPrefix(term, "foot"), strings.HasPrefix(term, "wezterm"):
		return 8
	}
	return 8
}

// checkTerm reproduces the terminfo lookup errors of the original implementation.
func checkTerm() error {
	term := os.Getenv("TERM")
	if term == "" {
		return fmt.Errorf("terminal entry not found: term not set")
	}
	if term == "dumb" {
		return fmt.Errorf("terminal not cursor addressable")
	}
	known := []string{"xterm", "xterm-256color", "screen", "screen-256color", "tmux", "tmux-256color", "linux", "rxvt", "rxvt-unicode", "rxvt-unicode-256color", "vt100", "vt102", "vt220", "ansi", "alacritty", "kitty", "xterm-kitty", "foot", "wezterm", "konsole", "konsole-256color", "gnome", "gnome-256color", "putty", "putty-256color", "st", "st-256color", "cygwin", "eterm", "aterm", "xterm-color", "xterm-16color", "xterm-88color", "rxvt-256color", "screen-16color", "screen-bce", "vte", "vte-256color", "xterm-new", "xterm-truecolor", "xterm-direct", "screen.xterm-256color", "tmux-direct", "screen-256color-bce", "rxvt-unicode-direct"}
	for _, k := range known {
		if k == term {
			return nil
		}
	}
	dirs := []string{os.Getenv("TERMINFO"), filepath.Join(homeDir(), ".terminfo"), "/etc/terminfo", "/lib/terminfo", "/usr/share/terminfo", "/usr/lib/terminfo", "/usr/share/lib/terminfo", "/usr/local/share/terminfo"}
	for _, d := range dirs {
		if d == "" {
			continue
		}
		if _, err := os.Stat(filepath.Join(d, term[:1], term)); err == nil {
			return nil
		}
		if _, err := os.Stat(filepath.Join(d, fmt.Sprintf("%02x", term[0]), term)); err == nil {
			return nil
		}
	}
	return fmt.Errorf("couldn't open terminfo ($TERM) file for %s: exit status 1", term)
}

func newTerminal() (*Terminal, error) {
	if err := checkTerm(); err != nil {
		return nil, err
	}
	t := &Terminal{colors: terminalColors(), out: os.Stdout}
	in, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		if isTerminal(os.Stdin.Fd()) {
			in = os.Stdin
		} else {
			return nil, fmt.Errorf("terminal entry not found: term not set")
		}
	}
	t.in = in
	if err := t.enterRaw(); err != nil {
		return nil, err
	}
	t.updateSize()
	t.keys = make(chan Key, 64)
	t.resize = make(chan struct{}, 1)
	t.stopInput = make(chan struct{})
	fmt.Fprint(t.out, "\x1b[?1049h\x1b[?25l\x1b[H\x1b[2J")
	go t.readInput()
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGWINCH)
	go func() {
		for range sig {
			select {
			case t.resize <- struct{}{}:
			default:
			}
		}
	}()
	return t, nil
}

func (t *Terminal) enterRaw() error {
	fd := t.in.Fd()
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t.oldTermio)), 0, 0, 0); errno != 0 {
		return fmt.Errorf("terminal entry not found: term not set")
	}
	raw := t.oldTermio
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw)), 0, 0, 0); errno != 0 {
		return fmt.Errorf("terminal entry not found: term not set")
	}
	t.rawSet = true
	return nil
}

func (t *Terminal) leaveRaw() {
	if t.rawSet {
		syscall.Syscall6(syscall.SYS_IOCTL, t.in.Fd(), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&t.oldTermio)), 0, 0, 0)
		t.rawSet = false
	}
}

// Suspend restores the terminal temporarily (used to spawn a shell).
func (t *Terminal) Suspend() {
	fmt.Fprint(t.out, "\x1b[0m\x1b[?25h\x1b[H\x1b[2J\x1b[?1049l")
	t.leaveRaw()
}

// Resume re-enters raw mode after a suspend.
func (t *Terminal) Resume() {
	t.enterRaw()
	fmt.Fprint(t.out, "\x1b[?1049h\x1b[?25l\x1b[H\x1b[2J")
	t.updateSize()
}

func (t *Terminal) Close() {
	close(t.stopInput)
	fmt.Fprint(t.out, "\x1b[0m\x1b[?25h\x1b[H\x1b[2J\x1b[?1049l")
	t.leaveRaw()
}

func (t *Terminal) updateSize() {
	var ws struct {
		Row, Col, X, Y uint16
	}
	w, h := 80, 24
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, t.out.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)), 0, 0, 0); errno == 0 && ws.Col > 0 && ws.Row > 0 {
		w, h = int(ws.Col), int(ws.Row)
	} else if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, t.in.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)), 0, 0, 0); errno == 0 && ws.Col > 0 && ws.Row > 0 {
		w, h = int(ws.Col), int(ws.Row)
	}
	t.w, t.h = w, h
	t.cells = make([]Cell, w*h)
	t.clear()
}

func (t *Terminal) clear() {
	for i := range t.cells {
		t.cells[i] = Cell{ch: " ", width: 1}
	}
}

// Put writes a single character cell at the given position.
func (t *Terminal) Put(x, y int, ch string, width int, st Style) {
	if x < 0 || y < 0 || x >= t.w || y >= t.h {
		return
	}
	t.cells[y*t.w+x] = Cell{ch: ch, width: width, style: st}
	if width == 2 && x+1 < t.w {
		t.cells[y*t.w+x+1] = Cell{ch: "", width: 0, style: st}
	}
}

// Fill fills a rectangle with spaces of the given style.
func (t *Terminal) Fill(x, y, w, h int, st Style) {
	for yy := y; yy < y+h; yy++ {
		for xx := x; xx < x+w; xx++ {
			t.Put(xx, yy, " ", 1, st)
		}
	}
}

// Print writes a string at the position clipped to maxWidth cells; returns the width used.
func (t *Terminal) Print(x, y int, s string, st Style, maxWidth int) int {
	used := 0
	for _, r := range s {
		w := runeWidth(r)
		if w == 0 {
			continue
		}
		if maxWidth >= 0 && used+w > maxWidth {
			break
		}
		t.Put(x+used, y, string(r), w, st)
		used += w
	}
	return used
}

func (t *Terminal) sgr(st Style) string {
	var b strings.Builder
	b.WriteString("\x1b[0")
	if st.bold {
		b.WriteString(";1")
	}
	b.WriteString(t.colorCode(st.fg, false))
	b.WriteString(t.colorCode(st.bg, true))
	b.WriteString("m")
	return b.String()
}

func (t *Terminal) colorCode(c Color, bg bool) string {
	switch c.kind {
	case colorDefault:
		return ""
	case colorRGB:
		if t.colors >= 1<<24 {
			if bg {
				return fmt.Sprintf(";48;2;%d;%d;%d", c.v>>16&0xff, c.v>>8&0xff, c.v&0xff)
			}
			return fmt.Sprintf(";38;2;%d;%d;%d", c.v>>16&0xff, c.v>>8&0xff, c.v&0xff)
		}
		n := 8
		if t.colors >= 256 {
			n = 256
		}
		return t.indexCode(nearestPalette(c.v, n), bg)
	default:
		idx := c.v
		if idx >= t.colors && t.colors < 256 {
			idx = nearestPalette(paletteRGB[idx&0xff], t.colors)
		}
		return t.indexCode(idx, bg)
	}
}

func (t *Terminal) indexCode(idx int, bg bool) string {
	if idx < 8 {
		if bg {
			return fmt.Sprintf(";%d", 40+idx)
		}
		return fmt.Sprintf(";%d", 30+idx)
	}
	if idx < 16 {
		if bg {
			return fmt.Sprintf(";%d", 100+idx-8)
		}
		return fmt.Sprintf(";%d", 90+idx-8)
	}
	if bg {
		return fmt.Sprintf(";48;5;%d", idx)
	}
	return fmt.Sprintf(";38;5;%d", idx)
}

// Flush renders the whole screen buffer.
func (t *Terminal) Flush() {
	var b strings.Builder
	b.WriteString("\x1b[?25l\x1b[H")
	var cur Style
	curSet := false
	for y := 0; y < t.h; y++ {
		b.WriteString(fmt.Sprintf("\x1b[%d;1H", y+1))
		for x := 0; x < t.w; x++ {
			c := t.cells[y*t.w+x]
			if c.width == 0 {
				continue
			}
			if !curSet || c.style != cur {
				b.WriteString(t.sgr(c.style))
				cur = c.style
				curSet = true
			}
			b.WriteString(c.ch)
		}
	}
	b.WriteString("\x1b[0m")
	t.out.WriteString(b.String())
}

// ---------- input ----------

type KeyType int

const (
	KeyRune KeyType = iota
	KeyUp
	KeyDown
	KeyLeft
	KeyRight
	KeyEnter
	KeyEscape
	KeyBackspace
	KeyDelete
	KeyTab
	KeyBacktab
	KeyHome
	KeyEnd
	KeyPgUp
	KeyPgDn
	KeyCtrlC
	KeyCtrlU
	KeyCtrlW
	KeyCtrlA
	KeyCtrlE
	KeyCtrlK
	KeyCtrlF
	KeyCtrlL
	KeyOther
)

type Key struct {
	typ KeyType
	r   rune
}

func (t *Terminal) readInput() {
	buf := make([]byte, 256)
	var pending []byte
	for {
		select {
		case <-t.stopInput:
			return
		default:
		}
		n, err := t.in.Read(buf)
		if err != nil {
			time.Sleep(10 * time.Millisecond)
			continue
		}
		pending = append(pending, buf[:n]...)
		for len(pending) > 0 {
			k, used, more := parseKey(pending)
			if more {
				// wait briefly for the rest of an escape sequence
				time.Sleep(30 * time.Millisecond)
				n2, _ := readNonBlocking(t.in, buf)
				if n2 > 0 {
					pending = append(pending, buf[:n2]...)
					continue
				}
				k, used, _ = parseKeyFinal(pending)
			}
			t.keys <- k
			pending = pending[used:]
		}
	}
}

func readNonBlocking(f *os.File, buf []byte) (int, error) {
	fd := int(f.Fd())
	var rfds syscall.FdSet
	rfds.Bits[fd/64] |= 1 << (uint(fd) % 64)
	tv := syscall.Timeval{Sec: 0, Usec: 0}
	n, err := syscall.Select(fd+1, &rfds, nil, nil, &tv)
	if err != nil || n == 0 {
		return 0, err
	}
	return f.Read(buf)
}

// parseKey decodes one key from the buffer; more is true if the sequence may be incomplete.
func parseKey(b []byte) (Key, int, bool) {
	if b[0] == 0x1b {
		if len(b) == 1 {
			return Key{typ: KeyEscape}, 1, true
		}
		if b[1] == '[' || b[1] == 'O' {
			// find the end of the CSI sequence
			for i := 2; i < len(b); i++ {
				c := b[i]
				if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '~' {
					return decodeCSI(b[1:i+1]), i + 1, false
				}
				if i > 16 {
					break
				}
			}
			return Key{typ: KeyEscape}, 1, true
		}
		return Key{typ: KeyEscape}, 1, false
	}
	return decodeByte(b)
}

func parseKeyFinal(b []byte) (Key, int, bool) {
	if b[0] == 0x1b {
		if len(b) > 1 && (b[1] == '[' || b[1] == 'O') {
			for i := 2; i < len(b); i++ {
				c := b[i]
				if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '~' {
					return decodeCSI(b[1:i+1]), i + 1, false
				}
			}
		}
		return Key{typ: KeyEscape}, 1, false
	}
	return decodeByte(b)
}

func decodeByte(b []byte) (Key, int, bool) {
	c := b[0]
	switch c {
	case '\r', '\n':
		return Key{typ: KeyEnter}, 1, false
	case '\t':
		return Key{typ: KeyTab}, 1, false
	case 0x7f, 0x08:
		return Key{typ: KeyBackspace}, 1, false
	case 0x03:
		return Key{typ: KeyCtrlC}, 1, false
	case 0x15:
		return Key{typ: KeyCtrlU}, 1, false
	case 0x17:
		return Key{typ: KeyCtrlW}, 1, false
	case 0x01:
		return Key{typ: KeyCtrlA}, 1, false
	case 0x05:
		return Key{typ: KeyCtrlE}, 1, false
	case 0x0b:
		return Key{typ: KeyCtrlK}, 1, false
	case 0x06:
		return Key{typ: KeyCtrlF}, 1, false
	case 0x0c:
		return Key{typ: KeyCtrlL}, 1, false
	}
	if c < 0x20 {
		return Key{typ: KeyOther}, 1, false
	}
	if !utf8.FullRune(b) {
		return Key{typ: KeyOther}, 1, len(b) < 4
	}
	r, size := utf8.DecodeRune(b)
	return Key{typ: KeyRune, r: r}, size, false
}

func decodeCSI(seq []byte) Key {
	s := string(seq)
	switch s {
	case "[A", "OA":
		return Key{typ: KeyUp}
	case "[B", "OB":
		return Key{typ: KeyDown}
	case "[C", "OC":
		return Key{typ: KeyRight}
	case "[D", "OD":
		return Key{typ: KeyLeft}
	case "[H", "OH", "[1~", "[7~":
		return Key{typ: KeyHome}
	case "[F", "OF", "[4~", "[8~":
		return Key{typ: KeyEnd}
	case "[5~":
		return Key{typ: KeyPgUp}
	case "[6~":
		return Key{typ: KeyPgDn}
	case "[3~":
		return Key{typ: KeyDelete}
	case "[Z":
		return Key{typ: KeyBacktab}
	case "OM":
		return Key{typ: KeyEnter}
	}
	if strings.HasPrefix(s, "[1;") || strings.HasPrefix(s, "[1;5") {
		switch s[len(s)-1] {
		case 'A':
			return Key{typ: KeyUp}
		case 'B':
			return Key{typ: KeyDown}
		case 'C':
			return Key{typ: KeyRight}
		case 'D':
			return Key{typ: KeyLeft}
		case 'H':
			return Key{typ: KeyHome}
		case 'F':
			return Key{typ: KeyEnd}
		}
	}
	return Key{typ: KeyOther}
}

// ---------- rune width ----------

func runeWidth(r rune) int {
	switch {
	case r == 0:
		return 0
	case r < 0x20 || (r >= 0x7f && r < 0xa0):
		return 0
	case r >= 0x300 && r <= 0x36f, r >= 0x200b && r <= 0x200f, r >= 0xfe00 && r <= 0xfe0f, r >= 0x20d0 && r <= 0x20ff:
		return 0
	case r >= 0x1100 && r <= 0x115f,
		r >= 0x2e80 && r <= 0x303e,
		r >= 0x3041 && r <= 0x33ff,
		r >= 0x3400 && r <= 0x4dbf,
		r >= 0x4e00 && r <= 0x9fff,
		r >= 0xa000 && r <= 0xa4cf,
		r >= 0xac00 && r <= 0xd7a3,
		r >= 0xf900 && r <= 0xfaff,
		r >= 0xfe30 && r <= 0xfe4f,
		r >= 0xff00 && r <= 0xff60,
		r >= 0xffe0 && r <= 0xffe6,
		r >= 0x1f300 && r <= 0x1f64f,
		r >= 0x1f900 && r <= 0x1f9ff,
		r >= 0x20000 && r <= 0x3fffd:
		return 2
	}
	return 1
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}
EOF
echo ok"}

