// span2 is a line of spans for the info modal.
type span2 []span

func (a *App) runTUI() error {
	term, err := newTerminal()
	if err != nil {
		return fmt.Errorf("error creating screen: %w", err)
	}
	t := &TUI{app: a, flags: a.flags, term: term, th: buildTheme(a.flags), marked: map[*Item]bool{}, ignored: map[string]bool{}}
	t.sortBy, t.sortOrder = "size", "desc"
	switch a.flags.Sorting.By {
	case "name", "size", "itemCount", "mtime":
		t.sortBy = a.flags.Sorting.By
	}
	switch a.flags.Sorting.Order {
	case "asc", "desc":
		t.sortOrder = a.flags.Sorting.Order
	}
	t.showApp = a.flags.ShowApparentSize
	t.showRel = a.flags.ShowRelativeSize
	t.showCount = a.flags.ShowItemCount
	t.showMtime = a.flags.ShowMTime
	t.askDelete = true
	t.resetHeader()
	err = t.run()
	term.Close()
	if err != nil {
		return err
	}
	if t.quitPath && t.current != nil {
		fmt.Println(t.current.Path())
	}
	return nil
}

func (t *TUI) resetHeader() {
	t.header = " gdu ~ Use arrow keys to navigate, press ? for help "
}

func (t *TUI) run() error {
	f := t.flags
	if f.InputFile != "" {
		file, err := os.Open(f.InputFile)
		if err != nil {
			return fmt.Errorf("opening input file: %w", err)
		}
		root, err := importJSON(file)
		file.Close()
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
		updateStats(root, map[uint64]bool{})
		t.root = root
		t.setCurrent(root, 0)
	} else if f.ShowDisks {
		devices, err := getDevices()
		if err != nil {
			return fmt.Errorf("loading mount points: %w", err)
		}
		t.devices = devices
		t.devMode = true
		t.selected = 0
	} else {
		if err := t.app.prepareFilters(); err != nil {
			return err
		}
		logInfof("Max cores set to %d", f.MaxCores)
		path := t.app.scanPath()
		if _, err := os.Stat(path); err != nil {
			return err
		}
		if f.ReadFromStorage && f.DbPath != "" {
			root, err := loadStorage(f.DbPath)
			if err != nil {
				return err
			}
			updateStats(root, map[uint64]bool{})
			t.root = root
			t.setCurrent(root, 0)
		} else {
			t.startScan(path, nil)
		}
	}
	return t.loop()
}

// startScan launches the analysis of path in the background.
func (t *TUI) startScan(path string, parent *Item) {
	logInfof("Analyzing path: %s", path)
	an := t.app.newAnalyzer()
	t.progress = an.progress
	t.scanning = true
	t.scanStart = time.Now()
	t.scanParent = parent
	t.scanPath = path
	t.modal = modalProgress
	done := make(chan *Item, 1)
	t.scanDone = done
	go func() {
		root := an.Analyze(path)
		done <- root
	}()
}

func (t *TUI) finishScan(root *Item) {
	t.scanning = false
	t.modal = modalNone
	if t.scanParent != nil {
		// rescan of a subdirectory: replace it in the tree
		parent := t.scanParent
		for i, c := range parent.Files {
			if c.Path() == t.scanPath {
				root.Name = c.Name
				root.BasePath = ""
				root.Parent = parent
				parent.Files[i] = root
				break
			}
		}
		updateStats(t.root, map[uint64]bool{})
		t.setCurrent(root, 0)
		return
	}
	if t.root != nil && t.current != nil && t.root.Path() == root.Path() {
		updateStats(root, map[uint64]bool{})
		t.root = root
		t.setCurrent(root, 0)
		return
	}
	updateStats(root, map[uint64]bool{})
	if t.flags.DbPath != "" && !t.flags.ReadFromStorage {
		dedupStoredLinks(root, map[uint64]bool{})
		_ = saveStorage(t.flags.DbPath, root)
	}
	t.root = root
	t.setCurrent(root, 0)
}

func (t *TUI) loop() error {
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	t.draw()
	for {
		select {
		case k := <-t.term.keys:
			if t.scanning {
				if (k.typ == KeyRune && (k.r == 'q' || k.r == 'Q')) || k.typ == KeyCtrlC {
					return nil
				}
				continue
			}
			quit, err := t.handleKey(k)
			if err != nil {
				return err
			}
			if quit {
				return nil
			}
			t.draw()
		case <-t.term.resize:
			t.term.updateSize()
			t.draw()
		case root := <-t.scanDone:
			t.finishScan(root)
			t.draw()
		case <-ticker.C:
			if t.scanning {
				t.draw()
			}
		}
	}
}

// ---------- state helpers ----------

func (t *TUI) setCurrent(dir *Item, sel int) {
	t.current = dir
	t.devMode = false
	t.selected = sel
	t.offset = 0
	t.rebuildRows()
}

func (t *TUI) isIgnored(it *Item) bool {
	return t.ignored[it.Path()]
}

func (t *TUI) itemSize(it *Item) int64 {
	if t.showApp {
		return it.Size
	}
	return it.Usage
}

func (t *TUI) sortKeySize(it *Item) int64 {
	return t.itemSize(it)
}

func (t *TUI) hasParentRow() bool {
	return t.current != nil && t.current.Parent != nil
}

// rebuildRows recomputes the visible rows of the current directory.
func (t *TUI) rebuildRows() {
	t.rows = nil
	if t.current == nil {
		return
	}
	if t.hasParentRow() {
		t.rows = append(t.rows, nil)
	}
	items := make([]*Item, 0, len(t.current.Files))
	filter := strings.ToLower(t.filter)
	for _, f := range t.current.Files {
		if filter != "" && !strings.Contains(strings.ToLower(f.Name), filter) {
			continue
		}
		items = append(items, f)
	}
	t.sortItems(items)
	t.rows = append(t.rows, items...)
	if t.selected >= len(t.rows) {
		t.selected = len(t.rows) - 1
	}
	if t.selected < 0 {
		t.selected = 0
	}
}

func (t *TUI) sortItems(items []*Item) {
	less := func(a, b *Item) bool {
		switch t.sortBy {
		case "name":
			return a.Name < b.Name
		case "itemCount":
			ca, cb := a.countValue(), b.countValue()
			if ca != cb {
				return ca < cb
			}
			return a.Name < b.Name
		case "mtime":
			if !a.Mtime.Equal(b.Mtime) {
				return a.Mtime.Before(b.Mtime)
			}
			return a.Name < b.Name
		default:
			sa, sb := t.sortKeySize(a), t.sortKeySize(b)
			if sa != sb {
				return sa < sb
			}
			return a.Name < b.Name
		}
	}
	sort.SliceStable(items, func(i, j int) bool { return less(items[i], items[j]) })
	if t.sortOrder == "desc" {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}
}

func (t *TUI) toggleSort(by string) {
	if t.sortBy == by {
		if t.sortOrder == "asc" {
			t.sortOrder = "desc"
		} else {
			t.sortOrder = "asc"
		}
	} else {
		t.sortBy = by
		t.sortOrder = "asc"
	}
	t.rebuildRows()
}

func (t *TUI) selectedItem() *Item {
	if t.devMode || t.selected < 0 || t.selected >= len(t.rows) {
		return nil
	}
	return t.rows[t.selected]
}

func (t *TUI) tableHeight() int {
	h := t.term.h - 3
	if t.flags.Style.Header.Hidden {
		h++
	}
	if h < 1 {
		h = 1
	}
	return h
}

func (t *TUI) rowCount() int {
	if t.devMode {
		return len(t.devices) + 1
	}
	return len(t.rows)
}

func (t *TUI) moveSelection(delta int) {
	n := t.rowCount()
	min := 0
	if t.devMode {
		min = 1
	}
	t.selected += delta
	if t.selected >= n {
		t.selected = n - 1
	}
	if t.selected < min {
		t.selected = min
	}
}

// ---------- totals ----------

func (t *TUI) totals() (usage, size int64, count int) {
	if t.current == nil {
		return
	}
	for _, it := range t.rows {
		if it == nil || t.isIgnored(it) {
			continue
		}
		usage += it.Usage
		size += it.Size
		count += it.countValue()
	}
	return
}

func (t *TUI) maxSizeAndTotal() (maxSize, total int64) {
	for _, it := range t.rows {
		if it == nil || t.isIgnored(it) {
			continue
		}
		s := t.itemSize(it)
		total += s
		if s > maxSize {
			maxSize = s
		}
	}
	return
}

// ---------- key handling ----------

func (t *TUI) handleKey(k Key) (bool, error) {
	if t.modal != modalNone {
		return t.handleModalKey(k)
	}
	if t.fileView {
		return t.handleFileViewKey(k), nil
	}
	if t.filtering {
		return t.handleFilterKey(k), nil
	}
	switch k.typ {
	case KeyCtrlC:
		return true, nil
	case KeyUp:
		t.moveSelection(-1)
	case KeyDown:
		t.moveSelection(1)
	case KeyPgUp:
		t.moveSelection(-t.tableHeight())
	case KeyPgDn:
		t.moveSelection(t.tableHeight())
	case KeyHome:
		t.moveSelection(-1 << 30)
	case KeyEnd:
		t.moveSelection(1 << 30)
	case KeyRight, KeyEnter:
		return t.enterSelected()
	case KeyLeft:
		t.goToParent()
	case KeyRune:
		return t.handleRune(k.r)
	}
	return false, nil
}

func (t *TUI) handleRune(r rune) (bool, error) {
	switch r {
	case 'q':
		return true, nil
	case 'Q':
		t.quitPath = true
		return true, nil
	case 'k':
		t.moveSelection(-1)
	case 'j':
		t.moveSelection(1)
	case 'g':
		t.moveSelection(-1 << 30)
	case 'G':
		t.moveSelection(1 << 30)
	case 'l':
		return t.enterSelected()
	case 'h':
		t.goToParent()
	case '?':
		t.modal = modalHelp
	case 'i':
		t.showInfo()
	case 'd':
		t.confirmDeletion(actionDelete)
	case 'e':
		t.confirmDeletion(actionEmpty)
	case 'v':
		t.viewFile()
	case 'o':
		t.openItem()
	case 'I':
		t.ignoreItem()
	case ' ':
		t.markItem()
	case 'n':
		if !t.devMode {
			t.toggleSort("name")
		}
	case 's':
		if !t.devMode {
			t.toggleSort("size")
		}
	case 'C':
		if !t.devMode {
			t.toggleSort("itemCount")
		}
	case 'M':
		if !t.devMode {
			t.toggleSort("mtime")
		}
	case 'a':
		t.showApp = !t.showApp
		t.rebuildRows()
	case 'B':
		t.showRel = !t.showRel
	case 'c':
		t.showCount = !t.showCount
	case 'm':
		t.showMtime = !t.showMtime
	case 'r':
		t.rescan()
	case 'E':
		if !t.devMode && t.current != nil {
			t.modal = modalExport
			t.exportName = "export.json"
			t.exportSet = false
			t.exportFocus = 0
			t.exportCur = len(t.exportName)
		}
	case '/':
		if !t.devMode {
			t.filtering = true
		}
	case 'b':
		t.spawnShell()
	}
	return false, nil
}

func (t *TUI) enterSelected() (bool, error) {
	if t.devMode {
		idx := t.selected - 1
		if idx < 0 || idx >= len(t.devices) {
			return false, nil
		}
		dev := t.devices[idx]
		if err := t.app.prepareFilters(); err != nil {
			return false, err
		}
		t.filter = ""
		t.filtering = false
		t.startScan(dev.MountPoint, nil)
		return false, nil
	}
	it := t.selectedItem()
	if t.current == nil {
		return false, nil
	}
	if it == nil {
		if t.hasParentRow() {
			t.goToParent()
		}
		return false, nil
	}
	if it.IsDir {
		t.filter = ""
		t.filtering = false
		t.setCurrent(it, 0)
	}
	return false, nil
}

func (t *TUI) goToParent() {
	if t.devMode || t.current == nil {
		return
	}
	if t.current.Parent == nil {
		if t.devices != nil {
			t.devMode = true
			t.selected = 1
			t.offset = 0
		}
		return
	}
	child := t.current
	t.filter = ""
	t.filtering = false
	parent := child.Parent
	if t.flags.CollapsePath {
		// jump over collapsed single-child chains
		for parent.Parent != nil && len(parent.Files) == 1 && parent.Files[0].IsDir {
			parent = parent.Parent
		}
	}
	t.setCurrent(parent, 0)
	for i, r := range t.rows {
		if r != nil && (r == child || containsItem(r, child)) {
			t.selected = i
			break
		}
	}
	t.ensureVisible()
}

func containsItem(dir, target *Item) bool {
	for dir != nil {
		if dir == target {
			return true
		}
		if len(dir.Files) == 1 && dir.Files[0].IsDir {
			dir = dir.Files[0]
			continue
		}
		return false
	}
	return false
}

func (t *TUI) ensureVisible() {
	h := t.tableHeight()
	if t.selected < t.offset {
		t.offset = t.selected
	}
	if t.selected-t.offset >= h {
		t.offset = t.selected - h + 1
	}
	if t.offset < 0 {
		t.offset = 0
	}
}

func (t *TUI) markItem() {
	it := t.selectedItem()
	if it == nil {
		return
	}
	if t.marked[it] {
		delete(t.marked, it)
	} else {
		t.marked[it] = true
	}
	t.moveSelection(1)
}

func (t *TUI) ignoreItem() {
	it := t.selectedItem()
	if it == nil {
		return
	}
	p := it.Path()
	if t.ignored[p] {
		delete(t.ignored, p)
	} else {
		t.ignored[p] = true
	}
}

func (t *TUI) rescan() {
	if t.devMode || t.current == nil {
		return
	}
	t.marked = map[*Item]bool{}
	t.startScan(t.current.Path(), t.current.Parent)
}

func (t *TUI) spawnShell() {
	if t.flags.NoSpawnShell {
		t.resetHeader()
		return
	}
	if t.current == nil {
		return
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	t.term.Suspend()
	cmd := exec.Command(shell)
	cmd.Dir = t.current.Path()
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	t.term.Resume()
}

func (t *TUI) openItem() {
	it := t.selectedItem()
	if it == nil {
		return
	}
	cmd := exec.Command("xdg-open", it.Path())
	_ = cmd.Start()
	go func() { _ = cmd.Wait() }()
}

func (t *TUI) viewFile() {
	it := t.selectedItem()
	if it == nil || it.IsDir {
		return
	}
	data, err := os.ReadFile(it.Path())
	if err != nil {
		t.showError(fmt.Sprintf("Error opening file: %v", err))
		return
	}
	content := strings.TrimRight(string(data), "\n")
	t.fileLines = strings.Split(content, "\n")
	if content == "" {
		t.fileLines = nil
	}
	t.fileOffset = 0
	t.filePath = it.Path()
	t.fileView = true
}

func (t *TUI) handleFileViewKey(k Key) bool {
	switch {
	case k.typ == KeyCtrlC:
		return true
	case k.typ == KeyEscape, k.typ == KeyRune && k.r == 'q':
		t.fileView = false
	case k.typ == KeyDown, k.typ == KeyRune && k.r == 'j':
		if t.fileOffset < len(t.fileLines)-1 {
			t.fileOffset++
		}
	case k.typ == KeyUp, k.typ == KeyRune && k.r == 'k':
		if t.fileOffset > 0 {
			t.fileOffset--
		}
	case k.typ == KeyPgDn:
		t.fileOffset += t.tableHeight()
		if t.fileOffset > len(t.fileLines)-1 {
			t.fileOffset = len(t.fileLines) - 1
		}
		if t.fileOffset < 0 {
			t.fileOffset = 0
		}
	case k.typ == KeyPgUp:
		t.fileOffset -= t.tableHeight()
		if t.fileOffset < 0 {
			t.fileOffset = 0
		}
	case k.typ == KeyHome, k.typ == KeyRune && k.r == 'g':
		t.fileOffset = 0
	case k.typ == KeyEnd, k.typ == KeyRune && k.r == 'G':
		t.fileOffset = len(t.fileLines) - t.tableHeight()
		if t.fileOffset < 0 {
			t.fileOffset = 0
		}
	}
	return false
}

func (t *TUI) handleFilterKey(k Key) bool {
	switch k.typ {
	case KeyCtrlC:
		return true
	case KeyEscape:
		t.filter = ""
		t.filtering = false
		t.rebuildRows()
	case KeyEnter:
		t.filtering = false
	case KeyBackspace:
		if len(t.filter) > 0 {
			r := []rune(t.filter)
			t.filter = string(r[:len(r)-1])
			t.rebuildRows()
		}
	case KeyCtrlU:
		t.filter = ""
		t.rebuildRows()
	case KeyCtrlW:
		s := strings.TrimRight(t.filter, " ")
		if i := strings.LastIndex(s, " "); i >= 0 {
			t.filter = s[:i+1]
		} else {
			t.filter = ""
		}
		t.rebuildRows()
	case KeyRune:
		t.filter += string(k.r)
		t.rebuildRows()
	}
	return false
}

// ---------- info / confirm / delete ----------

func (t *TUI) sp(text string, st Style) span { return span{text, st} }

func (t *TUI) showInfo() {
	if t.devMode || t.current == nil {
		return
	}
	it := t.selectedItem()
	if it == nil {
		if t.hasParentRow() {
			it = t.current.Parent
		} else {
			return
		}
	}
	white := Style{fg: cWhite}
	whiteB := Style{fg: cWhite, bold: true}
	numB := Style{fg: t.th.numberColor, bold: true}
	whiteBold := Style{fg: cWhite, bold: true}
	typ := "Directory"
	if !it.IsDir {
		if it.Flag == '@' {
			typ = "Other"
		} else {
			typ = "File"
		}
	}
	lines := []span2{
		{t.sp("Name:", whiteB), t.sp(" "+it.Name, white)},
		{t.sp("Path:", whiteB), t.sp(" "+it.Path(), white)},
		{t.sp("Type:", whiteB), t.sp(" "+typ, white)},
		{},
	}
	sizeLine := func(label string, size int64) span2 {
		num, unit := sizeParts(size, t.flags.UseSIPrefix, false, false)
		return span2{t.sp(label, white), t.sp(strings.TrimLeft(label, " ")[:0]+"", white), t.sp("", white), t.sp(label[:0], white), t.sp("", white), t.sp("", white),
			t.sp("", white)}[:0:0]
		_ = num
		_ = unit
		return nil
	}
	_ = sizeLine
	du, dunit := sizeParts(it.Usage, t.flags.UseSIPrefix, false, false)
	as, aunit := sizeParts(it.Size, t.flags.UseSIPrefix, false, false)
	lines = append(lines,
		span2{t.sp("   ", white), t.sp("Disk usage:", whiteBold), t.sp(" ", white), t.sp(du, numB), t.sp(" "+dunit+" (", whiteBold), t.sp(fmt.Sprint(it.Usage), numB), t.sp(" B)", whiteBold)},
		span2{t.sp("Apparent size:", whiteBold), t.sp(" ", white), t.sp(as, numB), t.sp(" "+aunit+" (", whiteBold), t.sp(fmt.Sprint(it.Size), numB), t.sp(" B)", whiteBold)},
	)
	if it.Mli != 0 && t.root != nil {
		var links []*Item
		collectHardlinks(t.root, it.Mli, &links)
		if len(links) > 0 {
			lines = append(lines, span2{}, span2{t.sp("Hard-linked files:", whiteBold)})
			for _, l := range links {
				lines = append(lines, span2{t.sp("    "+l.Path(), whiteBold)})
			}
		}
	}
	t.infoLines = lines
	t.modal = modalInfo
}

func (t *TUI) confirmDeletion(act confirmAction) {
	if t.devMode || t.current == nil {
		return
	}
	if t.flags.NoDelete {
		t.header = " Deletion is disabled!"
		return
	}
	it := t.selectedItem()
	if it == nil && len(t.marked) == 0 {
		return
	}
	t.confirmAct = act
	verb := "delete"
	if act == actionEmpty {
		verb = "empty"
	}
	if len(t.marked) > 0 {
		t.confirmText = fmt.Sprintf("Are you sure you want to %s \x00%d\x00 items?", verb, len(t.marked))
	} else {
		t.confirmText = fmt.Sprintf("Are you sure you want to %s %q?", verb, it.Name)
	}
	if !t.askDelete {
		t.performDeletion()
		return
	}
	t.confirmBtn = 0
	t.modal = modalConfirm
}

func (t *TUI) performDeletion() {
	var targets []*Item
	if len(t.marked) > 0 {
		for it := range t.marked {
			targets = append(targets, it)
		}
		sort.Slice(targets, func(i, j int) bool { return targets[i].Name < targets[j].Name })
	} else if it := t.selectedItem(); it != nil {
		targets = append(targets, it)
	}
	for _, it := range targets {
		var err error
		if t.confirmAct == actionEmpty {
			err = emptyItem(it)
		} else {
			err = os.RemoveAll(it.Path())
		}
		if err != nil {
			verb := "delete"
			if t.confirmAct == actionEmpty {
				verb = "empty"
			}
			t.showError(fmt.Sprintf("Can't %s %s: %v", verb, it.Name, err))
			break
		}
		if t.confirmAct == actionEmpty {
			if it.IsDir {
				it.Files = nil
			} else {
				it.Size = 0
				it.Usage = 0
			}
		} else if it.Parent != nil {
			it.Parent.removeFile(it)
		}
		delete(t.marked, it)
	}
	t.marked = map[*Item]bool{}
	if t.root != nil {
		updateStats(t.root, map[uint64]bool{})
	}
	t.rebuildRows()
	t.ensureVisible()
}

func emptyItem(it *Item) error {
	if it.IsDir {
		entries, err := os.ReadDir(it.Path())
		if err != nil {
			return err
		}
		for _, e := range entries {
			if err := os.RemoveAll(filepath.Join(it.Path(), e.Name())); err != nil {
				return err
			}
		}
		return nil
	}
	return os.Truncate(it.Path(), 0)
}

func (t *TUI) showError(text string) {
	t.errorText = text
	t.modal = modalError
}

func (t *TUI) handleModalKey(k Key) (bool, error) {
	if k.typ == KeyCtrlC {
		return true, nil
	}
	switch t.modal {
	case modalHelp, modalInfo:
		if k.typ == KeyEscape || k.typ == KeyEnter || (k.typ == KeyRune && (k.r == 'q' || k.r == '?' || k.r == 'i')) {
			t.modal = modalNone
			t.resetHeader()
		}
	case modalError:
		if k.typ == KeyEscape || k.typ == KeyEnter || (k.typ == KeyRune && k.r == 'q') {
			t.modal = modalNone
			t.resetHeader()
		}
	case modalConfirm:
		switch k.typ {
		case KeyEscape:
			t.modal = modalNone
			t.resetHeader()
		case KeyRight, KeyTab, KeyDown:
			t.confirmBtn = (t.confirmBtn + 1) % 3
		case KeyLeft, KeyBacktab, KeyUp:
			t.confirmBtn = (t.confirmBtn + 2) % 3
		case KeyEnter:
			t.modal = modalNone
			t.resetHeader()
			switch t.confirmBtn {
			case 1:
				t.performDeletion()
			case 2:
				t.askDelete = false
				t.performDeletion()
			}
		}
	case modalExport:
		return t.handleExportKey(k), nil
	case modalProgress:
		if k.typ == KeyRune && (k.r == 'q' || k.r == 'Q') {
			return true, nil
		}
	}
	return false, nil
}

func (t *TUI) handleExportKey(k Key) bool {
	switch k.typ {
	case KeyEscape:
		t.modal = modalNone
		t.resetHeader()
		return false
	case KeyTab, KeyDown:
		t.exportFocus = (t.exportFocus + 1) % 2
		return false
	case KeyBacktab, KeyUp:
		t.exportFocus = (t.exportFocus + 1) % 2
		return false
	}
	if t.exportFocus == 0 {
		switch k.typ {
		case KeyEnter:
			t.exportFocus = 1
		case KeyBackspace:
			r := []rune(t.exportName)
			if t.exportCur > 0 && t.exportCur <= len(r) {
				r = append(r[:t.exportCur-1], r[t.exportCur:]...)
				t.exportCur--
				t.exportName = string(r)
				t.exportSet = true
			}
		case KeyDelete:
			r := []rune(t.exportName)
			if t.exportCur < len(r) {
				r = append(r[:t.exportCur], r[t.exportCur+1:]...)
				t.exportName = string(r)
				t.exportSet = true
			}
		case KeyLeft:
			if t.exportCur > 0 {
				t.exportCur--
			}
		case KeyRight:
			if t.exportCur < len([]rune(t.exportName)) {
				t.exportCur++
			}
		case KeyHome, KeyCtrlA:
			t.exportCur = 0
		case KeyEnd, KeyCtrlE:
			t.exportCur = len([]rune(t.exportName))
		case KeyCtrlU:
			t.exportName = ""
			t.exportCur = 0
			t.exportSet = true
		case KeyCtrlK:
			r := []rune(t.exportName)
			if t.exportCur < len(r) {
				t.exportName = string(r[:t.exportCur])
			}
			t.exportSet = true
		case KeyCtrlW:
			r := []rune(t.exportName[:0])
			_ = r
			s := []rune(t.exportName)
			i := t.exportCur
			for i > 0 && s[i-1] == ' ' {
				i--
			}
			for i > 0 && s[i-1] != ' ' {
				i--
			}
			t.exportName = string(append(s[:i:i], s[t.exportCur:]...))
			t.exportCur = i
			t.exportSet = true
		case KeyRune:
			r := []rune(t.exportName)
			r = append(r[:t.exportCur], append([]rune{k.r}, r[t.exportCur:]...)...)
			t.exportName = string(r)
			t.exportCur++
			t.exportSet = true
		}
		return false
	}
	if k.typ == KeyEnter {
		t.modal = modalNone
		t.resetHeader()
		name := ""
		if t.exportSet {
			name = t.exportName
		}
		if name == "" || t.root == nil {
			return false
		}
		w, cl, err := openExportFile(name)
		if err != nil {
			logInfo(err.Error())
			return false
		}
		if err := exportJSON(w, t.root); err != nil {
			logInfo(err.Error())
		}
		cl()
	}
	return false
}
EOF
echo ok"}

