package main

import (
	"fmt"
	"strings"
	"time"
)

var barChars = []string{" ", "▏", "▎", "▍", "▌", "▋", "▊", "▉"}

// wrapFirstLine returns the part of text that fits into width using word wrapping.
func wrapFirstLine(text string, width int) string {
	if stringWidth(text) <= width {
		return text
	}
	var tokens []string
	cur := ""
	for _, r := range text {
		cur += string(r)
		if r == ' ' {
			tokens = append(tokens, cur)
			cur = ""
		}
	}
	if cur != "" {
		tokens = append(tokens, cur)
	}
	out := ""
	used := 0
	for _, tok := range tokens {
		w := stringWidth(tok)
		if used+w > width {
			break
		}
		out += tok
		used += w
	}
	if out == "" {
		// no break opportunity: hard clip
		return clipString(text, width)
	}
	return out
}

func clipString(s string, width int) string {
	out := ""
	used := 0
	for _, r := range s {
		w := runeWidth(r)
		if used+w > width {
			break
		}
		out += string(r)
		used += w
	}
	return out
}

// printSpans prints styled spans at x,y clipped to maxX (exclusive); returns the end x.
func (t *TUI) printSpans(x, y int, spans []span, maxX int) int {
	for _, s := range spans {
		for _, r := range s.text {
			w := runeWidth(r)
			if w == 0 {
				continue
			}
			if x+w > maxX {
				return x
			}
			t.term.Put(x, y, string(r), w, s.style)
			x += w
		}
	}
	return x
}

func spansWidth(spans []span) int {
	w := 0
	for _, s := range spans {
		w += stringWidth(s.text)
	}
	return w
}

func spansText(spans []span) string {
	var b strings.Builder
	for _, s := range spans {
		b.WriteString(s.text)
	}
	return b.String()
}

// ---------- main drawing ----------

func (t *TUI) draw() {
	tm := t.term
	tm.clear()
	y := 0
	if !t.flags.Style.Header.Hidden {
		t.drawHeader(y)
		y++
	}
	t.drawPathLine(y)
	y++
	h := t.tableHeight()
	switch {
	case t.scanning && t.modal == modalProgress:
		// nothing in the table area
	case t.fileView:
		t.drawFileView(y, h)
	case t.devMode:
		t.drawDeviceTable(y, h)
	default:
		t.drawFileTable(y, h)
	}
	t.drawFooter(tm.h - 1)
	t.drawModal()
	tm.Flush()
}

func (t *TUI) drawHeader(y int) {
	st := Style{fg: t.th.headerFg, bg: t.th.headerBg}
	t.term.Fill(0, y, t.term.w, 1, st)
	t.term.Print(0, y, wrapFirstLine(t.header, t.term.w), st, t.term.w)
}

func (t *TUI) drawPathLine(y int) {
	if t.scanning || t.current == nil {
		return
	}
	if t.devMode && t.current == nil {
		return
	}
	path := t.current.Path()
	if t.fileView {
		path = t.filePath
	}
	text := " --- " + path + " ---"
	t.term.Print(0, y, wrapFirstLine(text, t.term.w), Style{bold: true}, t.term.w)
}

func (t *TUI) drawFileView(y, h int) {
	st := Style{fg: cWhite, bg: cBlack}
	t.term.Fill(0, y, t.term.w, h, st)
	for i := 0; i < h; i++ {
		idx := t.fileOffset + i
		if idx >= len(t.fileLines) {
			break
		}
		line := strings.ReplaceAll(t.fileLines[idx], "\t", "    ")
		t.term.Print(0, y+i, line, st, t.term.w)
	}
}

// sizeField formats a size for the table (10 cells wide including the unit).
func (t *TUI) sizeField(size int64) (string, string) {
	num, unit := sizeParts(size, t.flags.UseSIPrefix, false, false)
	w := 10 - 1 - len(unit)
	if len(num) < w {
		num = strings.Repeat(" ", w-len(num)) + num
	}
	return num, " " + unit
}

func (t *TUI) usageBar(part int) string {
	if part < 0 {
		part = 0
	}
	if part > 100 {
		part = 100
	}
	full := part / 10
	frac := (part % 10) * 8 / 10
	var b strings.Builder
	for i := 0; i < full && i < 10; i++ {
		if t.flags.NoUnicode {
			b.WriteString("#")
		} else {
			b.WriteString("█")
		}
	}
	if full < 10 {
		if t.flags.NoUnicode {
			if frac > 0 {
				b.WriteString("#")
			} else {
				b.WriteString(" ")
			}
		} else {
			b.WriteString(barChars[frac])
		}
		for i := full + 1; i < 10; i++ {
			b.WriteString(" ")
		}
	}
	if t.flags.NoUnicode {
		return " " + b.String() + "|"
	}
	return " " + b.String() + "▏"
}

// itemRow builds the spans of one table row.
func (t *TUI) itemRow(it *Item, maxSize, total int64, anyMarked bool) []span {
	marked := t.marked[it]
	ignored := t.isIgnored(it)
	base := Style{}
	if marked {
		base = Style{fg: t.th.markFg, bg: t.th.markB}
	} else if ignored {
		base = Style{fg: t.th.ignoredColor}
	}
	bold := base
	bold.bold = true
	numSt := bold
	dirSt := bold
	if !marked && !ignored {
		numSt.fg = t.th.numberColor
		dirSt.fg = t.th.dirColor
	}
	var spans []span
	spans = append(spans, span{string(it.Flag), base})
	num, unit := t.sizeField(t.itemSize(it))
	spans = append(spans, span{num, numSt})
	part := 0
	if !ignored {
		size := t.itemSize(it)
		ref := total
		if t.showRel {
			ref = maxSize
		}
		if ref > 0 {
			part = int(float64(size) / float64(ref) * 100)
		}
	}
	bar := t.usageBar(part)
	if ignored {
		bar = t.usageBar(0)
	}
	spans = append(spans, span{unit + bar, bold})
	if t.showCount {
		spans = append(spans, span{fmt.Sprintf("%6d", it.displayCount()), numSt}, span{" ", bold})
	}
	if t.showMtime {
		spans = append(spans, span{it.Mtime.Format("2006-01-02 15:04:05") + " ", numSt})
	}
	if anyMarked {
		if marked {
			spans = append(spans, span{"✓ ", bold})
		} else {
			spans = append(spans, span{"  ", bold})
		}
	}
	if it.IsDir {
		spans = append(spans, span{"/" + it.Name, dirSt})
	} else {
		spans = append(spans, span{it.Name, bold})
	}
	return spans
}

func (t *TUI) parentRow(anyMarked bool) []span {
	pad := strings.Repeat(" ", 25)
	if anyMarked {
		pad += "  "
	}
	return []span{{pad, Style{}}, {"/..", Style{bold: true}}}
}

func (t *TUI) anyMarkedVisible() bool {
	for _, it := range t.rows {
		if it != nil && t.marked[it] {
			return true
		}
	}
	return false
}

func (t *TUI) drawFileTable(y, h int) {
	if t.current == nil {
		return
	}
	t.ensureVisible()
	maxSize, total := t.maxSizeAndTotal()
	anyMarked := t.anyMarkedVisible()
	type rowData struct {
		spans []span
		item  *Item
		sel   bool
	}
	var rows []rowData
	maxW := 0
	for i := t.offset; i < len(t.rows) && i-t.offset < h; i++ {
		it := t.rows[i]
		var sp []span
		if it == nil {
			sp = t.parentRow(anyMarked)
		} else {
			sp = t.itemRow(it, maxSize, total, anyMarked)
		}
		w := spansWidth(sp)
		if w > maxW {
			maxW = w
		}
		rows = append(rows, rowData{sp, it, i == t.selected})
	}
	cellW := maxW + 1
	if cellW > t.term.w {
		cellW = t.term.w
	}
	for i, r := range rows {
		ry := y + i
		if r.sel {
			st := Style{fg: t.th.selFg, bg: t.th.selBg, bold: true}
			t.term.Fill(0, ry, cellW, 1, st)
			t.term.Print(0, ry, spansText(r.spans), st, cellW)
			continue
		}
		if r.item != nil && t.marked[r.item] {
			t.term.Fill(0, ry, cellW, 1, Style{fg: t.th.markFg, bg: t.th.markB})
		}
		t.printSpans(0, ry, r.spans, t.term.w)
	}
}

// ---------- device table ----------

func (t *TUI) deviceRows() ([][]span, []int) {
	white := Style{fg: cWhite}
	header := []span{{"Device name", white}, {"Size", white}, {"Used", white}, {"Used part", white}, {"Free", white}, {"Mount point", white}}
	rows := [][]span{header}
	widths := make([]int, 6)
	for i, c := range header {
		widths[i] = stringWidth(c.text)
	}
	for _, d := range t.devices {
		used := d.Size - d.Free
		part := 0
		if d.Size > 0 {
			part = int(float64(used) / float64(d.Size) * 100)
		}
		cells := []span{
			{d.Name, Style{fg: t.th.dirColor, bold: true}},
			{formatSizePlain(d.Size, t.flags.UseSIPrefix, false, false), white},
			{formatSizePlain(used, t.flags.UseSIPrefix, false, false), white},
			{" " + t.usageBar(part), white},
			{formatSizePlain(d.Free, t.flags.UseSIPrefix, false, false), white},
			{d.MountPoint, Style{fg: t.th.dirColor, bold: true}},
		}
		for i, c := range cells {
			if w := stringWidth(c.text); w > widths[i] {
				widths[i] = w
			}
		}
		rows = append(rows, cells)
	}
	return rows, widths
}

func (t *TUI) drawDeviceTable(y, h int) {
	rows, widths := t.deviceRows()
	// header row is fixed; scroll the rest
	if t.selected < 1 {
		t.selected = 1
	}
	visible := h - 1
	if visible < 1 {
		visible = 1
	}
	if t.selected-1 < t.offset {
		t.offset = t.selected - 1
	}
	if t.selected-1-t.offset >= visible {
		t.offset = t.selected - visible
	}
	if t.offset < 0 {
		t.offset = 0
	}
	totalW := 0
	for _, w := range widths {
		totalW += w + 1
	}
	drawRow := func(ry int, cells []span, selected bool) {
		if selected {
			st := Style{fg: t.th.selFg, bg: t.th.selBg, bold: true}
			w := totalW
			if w > t.term.w {
				w = t.term.w
			}
			t.term.Fill(0, ry, w, 1, st)
		}
		x := 0
		for i, c := range cells {
			st := c.style
			if selected {
				st = Style{fg: t.th.selFg, bg: t.th.selBg, bold: true}
			}
			// used number highlighted
			if i == 2 && !selected && ry != y {
				num, unit := sizeParts(0, false, false, false)
				_ = num
				_ = unit
				parts := strings.SplitN(c.text, " ", 2)
				if len(parts) == 2 {
					numSt := Style{fg: cYellow, bold: true}
					if !t.th.useColors {
						numSt = Style{fg: cWhite, bold: true}
					}
					t.printSpans(x, ry, []span{{parts[0], numSt}, {" " + parts[1], Style{fg: cWhite, bold: true}}}, t.term.w)
				} else {
					t.term.Print(x, ry, c.text, st, t.term.w-x)
				}
			} else {
				t.term.Print(x, ry, c.text, st, t.term.w-x)
			}
			x += widths[i] + 1
			if x >= t.term.w {
				break
			}
		}
	}
	drawRow(y, rows[0], false)
	for i := 0; i < visible; i++ {
		idx := 1 + t.offset + i
		if idx >= len(rows) {
			break
		}
		drawRow(y+1+i, rows[idx], idx == t.selected)
	}
}

// ---------- footer ----------

func (t *TUI) footerSpans() []span {
	textSt := Style{fg: t.th.footerFg, bg: t.th.footerTextBg}
	numSt := Style{fg: t.th.footerNum, bg: t.th.footerTextBg, bold: true}
	var spans []span
	if t.scanning && t.modal == modalProgress {
		return []span{{" No items to display. ", textSt}}
	}
	if t.devMode {
		var total int64
		for _, d := range t.devices {
			total += d.Size - d.Free
		}
		num, unit := sizeParts(total, t.flags.UseSIPrefix, false, false)
		spans = append(spans, span{" Total usage: ", textSt}, span{num, numSt}, span{" " + unit + " Sorting by: size desc", textSt})
		return spans
	}
	if t.current == nil {
		return nil
	}
	usage, size, count := t.totals()
	if len(t.marked) > 0 {
		spans = append(spans, span{" Selected items: ", textSt}, span{fmt.Sprint(len(t.marked)), numSt}, span{" ", textSt})
		spans = append(spans, span{"Total disk usage: ", textSt})
	} else {
		spans = append(spans, span{" Total disk usage: ", textSt})
	}
	un, uu := sizeParts(usage, t.flags.UseSIPrefix, false, false)
	sn, su := sizeParts(size, t.flags.UseSIPrefix, false, false)
	spans = append(spans, span{un, numSt}, span{" " + uu + " Apparent size: ", textSt}, span{sn, numSt}, span{" " + su + " Items: ", textSt}, span{fmt.Sprint(count), numSt})
	spans = append(spans, span{" Sorting by: " + t.sortBy + " " + t.sortOrder, textSt})
	return spans
}

func (t *TUI) drawFooter(y int) {
	fill := Style{bg: t.th.footerBg}
	t.term.Fill(0, y, t.term.w, 1, fill)
	x := 0
	width := t.term.w
	if t.filtering || (t.filter != "" && !t.devMode) {
		fw := t.term.w / 6
		fst := Style{fg: t.th.fieldFg, bg: t.th.fieldBg}
		t.term.Fill(0, y, fw, 1, fst)
		t.term.Print(0, y, clipString(t.filter, fw), fst, fw)
		x = fw
		width -= fw
	}
	spans := t.footerSpans()
	full := spansText(spans)
	line := wrapFirstLine(full, width)
	// print spans up to the wrapped length
	remaining := len(line)
	var out []span
	for _, s := range spans {
		if remaining <= 0 {
			break
		}
		if len(s.text) <= remaining {
			out = append(out, s)
			remaining -= len(s.text)
		} else {
			out = append(out, span{s.text[:remaining], s.style})
			remaining = 0
		}
	}
	t.printSpans(x, y, out, t.term.w)
}

// ---------- modals ----------

func (t *TUI) drawBox(x, y, w, h int, double bool, bg Color, title string, titleColor Color) {
	st := Style{bg: bg}
	for yy := y; yy < y+h; yy++ {
		for xx := x; xx < x+w; xx++ {
			t.term.Put(xx, yy, " ", 1, st)
		}
	}
	var tl, tr, bl, br, hz, vt string
	if double {
		tl, tr, bl, br, hz, vt = "╔", "╗", "╚", "╝", "═", "║"
	} else {
		tl, tr, bl, br, hz, vt = "┌", "┐", "└", "┘", "─", "│"
	}
	for xx := x + 1; xx < x+w-1; xx++ {
		t.term.Put(xx, y, hz, 1, st)
		t.term.Put(xx, y+h-1, hz, 1, st)
	}
	for yy := y + 1; yy < y+h-1; yy++ {
		t.term.Put(x, yy, vt, 1, st)
		t.term.Put(x+w-1, yy, vt, 1, st)
	}
	t.term.Put(x, y, tl, 1, st)
	t.term.Put(x+w-1, y, tr, 1, st)
	t.term.Put(x, y+h-1, bl, 1, st)
	t.term.Put(x+w-1, y+h-1, br, 1, st)
	if title != "" && w > 4 {
		tw := stringWidth(title)
		inner := w - 2
		if tw > inner {
			title = clipString(title, inner)
			tw = inner
		}
		tx := x + 1 + (inner-tw+1)/2
		t.term.Print(tx, y, title, Style{fg: titleColor, bg: bg}, inner)
	}
}

func (t *TUI) drawModal() {
	switch t.modal {
	case modalHelp:
		t.drawHelp()
	case modalInfo:
		t.drawInfo()
	case modalConfirm:
		t.drawConfirm()
	case modalError:
		t.drawErrorModal()
	case modalExport:
		t.drawExport()
	case modalProgress:
		t.drawProgress()
	}
}

func (t *TUI) drawHelp() {
	W, H := t.term.w, t.term.h
	w := 80
	h := 36
	if h > H {
		h = H
	}
	x := (W - w) / 2
	y := (H - h) / 2
	bg := cBlack
	t.drawBox(x, y, w, h, true, bg, " gdu help ", t.th.titleColor)
	white := Style{fg: cWhite, bg: bg}
	keySt := Style{fg: t.th.helpKey, bg: bg}
	if !t.th.useColors {
		keySt = Style{fg: cWhite, bg: bg, bold: true}
	}
	maxLines := h - 6
	for i, hl := range helpLines {
		if i >= maxLines {
			break
		}
		ly := y + 3 + i
		lx := x + 3
		if hl.raw != "" {
			t.term.Print(lx, ly, hl.raw, white, w-5)
			continue
		}
		if hl.key == "" {
			continue
		}
		pad := 18 - len(hl.key)
		if i == 0 {
			pad = 7
		}
		gap := 23 - pad - len(hl.key)
		spans := []span{{strings.Repeat(" ", pad), white}, {hl.key + strings.Repeat(" ", gap), keySt}, {hl.desc, white}}
		t.printSpans(lx, ly, spans, x+w-1)
	}
}

func (t *TUI) drawInfo() {
	W, H := t.term.w, t.term.h
	w := 80
	h := len(t.infoLines) + 6
	x := (W - w) / 2
	y := (H - h) / 2
	bg := cBlack
	t.drawBox(x, y, w, h, false, bg, " Item info ", t.th.titleColor)
	for i, line := range t.infoLines {
		ly := y + 3 + i
		var spans []span
		for _, s := range line {
			st := s.style
			st.bg = bg
			spans = append(spans, span{s.text, st})
		}
		t.printSpans(x+3, ly, spans, x+w-1)
	}
}

// modalLayout computes the tview Modal geometry for the given text and buttons.
func (t *TUI) modalLayout(text string, buttons []string) (x, y, w, h int, lines []string, innerW int) {
	W, H := t.term.w, t.term.h
	buttonsWidth := 0
	for _, b := range buttons {
		buttonsWidth += stringWidth(b) + 4 + 2
	}
	buttonsWidth -= 2
	width := W / 3
	if width < buttonsWidth {
		width = buttonsWidth
	}
	lines = wordWrap(text, width)
	h = len(lines) + 6
	w = width + 4
	x = (W - w) / 2
	y = (H - h) / 2
	return x, y, w, h, lines, width
}

// wordWrap splits text into lines of at most width cells, breaking at spaces.
func wordWrap(text string, width int) []string {
	var lines []string
	rest := text
	for rest != "" {
		if stringWidth(rest) <= width {
			lines = append(lines, rest)
			break
		}
		line := wrapFirstLine(rest, width)
		if line == "" {
			line = clipString(rest, width)
		}
		rest = strings.TrimLeft(rest[len(line):], " ")
		lines = append(lines, strings.TrimRight(line, " "))
	}
	return lines
}

func (t *TUI) drawButtons(x, y, areaW int, buttons []string, focus int, bg Color) {
	totalW := 0
	for _, b := range buttons {
		totalW += stringWidth(b) + 4 + 1
	}
	totalW--
	bx := x + (areaW-totalW)/2
	for i, b := range buttons {
		st := Style{fg: t.th.buttonFg, bg: t.th.buttonBg}
		if i == focus {
			st = Style{fg: t.th.buttonFocFg, bg: t.th.buttonFocBg}
		}
		t.term.Fill(bx, y, stringWidth(b)+4, 1, st)
		t.term.Print(bx+2, y, b, st, stringWidth(b))
		bx += stringWidth(b) + 4 + 1
	}
}

func (t *TUI) drawConfirm() {
	plain := strings.ReplaceAll(t.confirmText, "\x00", "")
	buttons := []string{"no", "yes", "don't ask me again"}
	x, y, w, h, lines, innerW := t.modalLayout(plain, buttons)
	t.drawBox(x, y, w, h, true, t.th.modalBorderBg, "", cDefault)
	inner := Style{bg: t.th.modalBg}
	t.term.Fill(x+1, y+1, w-2, h-2, inner)
	// text with the bold segment between \x00 markers
	boldRanges := boldSegments(t.confirmText)
	pos := 0
	for i, line := range lines {
		lw := stringWidth(line)
		lx := x + 2 + (innerW-lw+1)/2
		idx := strings.Index(plain[pos:], line)
		start := pos
		if idx >= 0 {
			start = pos + idx
		}
		cx := lx
		for j, r := range line {
			st := Style{fg: cWhite, bg: t.th.modalBg}
			if boldRanges[start+j] {
				st.bold = true
			}
			t.term.Put(cx, y+2+i, string(r), runeWidth(r), st)
			cx += runeWidth(r)
		}
		pos = start + len(line)
	}
	t.drawButtons(x+2, y+2+len(lines)+1, innerW, buttons, t.confirmBtn, t.th.modalBg)
}

// boldSegments returns for each byte of the plain text whether it is inside \x00 markers.
func boldSegments(marked string) []bool {
	out := make([]bool, 0, len(marked))
	bold := false
	for i := 0; i < len(marked); i++ {
		if marked[i] == 0 {
			bold = !bold
			continue
		}
		out = append(out, bold)
	}
	return append(out, false)
}

func (t *TUI) drawErrorModal() {
	buttons := []string{"ok"}
	x, y, w, h, lines, innerW := t.modalLayout(t.errorText, buttons)
	t.drawBox(x, y, w, h, true, t.th.errorBg, "", cDefault)
	for i, line := range lines {
		lw := stringWidth(line)
		lx := x + 2 + (innerW-lw+1)/2
		t.term.Print(lx, y+2+i, line, Style{fg: cWhite, bg: t.th.errorBg}, lw)
	}
	t.drawButtons(x+2, y+2+len(lines)+1, innerW, buttons, 0, t.th.errorBg)
}

func (t *TUI) drawExport() {
	W, H := t.term.w, t.term.h
	w, h := 50, 7
	x := (W - w) / 2
	y := (H - h) / 2
	bg := cBlack
	t.drawBox(x, y, w, h, true, bg, " Export data to JSON ", t.th.titleColor)
	label := Style{fg: t.th.labelColor, bg: bg}
	t.term.Print(x+2, y+2, "File name", label, 9)
	fieldSt := Style{fg: t.th.fieldFg, bg: t.th.fieldBg}
	fx := x + 12
	t.term.Fill(fx, y+2, 30, 1, fieldSt)
	t.term.Print(fx, y+2, clipString(t.exportName, 30), fieldSt, 30)
	// button
	btn := "Export"
	bw := stringWidth(btn) + 4
	bx := x + 2 + (w-4-bw)/2
	st := Style{fg: cWhite, bg: cBlue}
	if !t.th.useColors {
		st = Style{fg: cWhite, bg: cWhite}
	}
	if t.exportFocus == 1 {
		st = Style{fg: cBlue, bg: cWhite}
		if !t.th.useColors {
			st = Style{fg: cBlack, bg: cWhite}
		}
	}
	t.term.Fill(bx, y+4, bw, 1, st)
	t.term.Print(bx+2, y+4, btn, st, bw)
}

func shortenPath(p string, maxLen int) string {
	if len(p) <= maxLen {
		return p
	}
	parts := strings.Split(p, "/")
	if len(parts) < 3 {
		return p
	}
	last := parts[len(parts)-1]
	head := parts[:len(parts)-1]
	cand := p
	for len(head) > 1 {
		head = head[:len(head)-1]
		cand = strings.Join(head, "/") + "/.../" + last
		if len(cand) <= maxLen {
			return cand
		}
	}
	return cand
}

func (t *TUI) drawProgress() {
	W, H := t.term.w, t.term.h
	// horizontal flex (1, 50, 1)
	s1 := W / 52
	rest := W - s1
	mid := rest * 50 / 51
	h := 8
	x := s1
	y := (H - h) / 2
	bg := cBlack
	t.drawBox(x, y, mid, h, false, bg, " Scanning... ", t.th.titleColor)
	items, size, cur := int64(0), int64(0), ""
	if t.progress != nil {
		items, size, cur = t.progress.snapshot()
	}
	white := Style{fg: cWhite, bg: bg}
	numSt := Style{fg: t.th.numberColor, bg: bg, bold: true}
	if !t.th.useColors {
		numSt = Style{fg: cWhite, bg: bg, bold: true}
	}
	num, unit := sizeParts(size, t.flags.UseSIPrefix, false, false)
	elapsed := time.Since(t.scanStart).Round(time.Second)
	line1 := []span{{"Total items: ", white}, {thousands(items), numSt}, {", size: ", white}, {num, numSt}, {" " + unit + ", elapsed time: ", white}, {fmt.Sprintf("%ds", int(elapsed.Seconds())), numSt}}
	maxLen := t.flags.Style.ProgressModal.CurrentItemNameMaxLen
	if maxLen <= 0 {
		maxLen = 74
	}
	line2 := []span{{"Current item: ", white}, {shortenPath(cur, maxLen), Style{fg: cWhite, bg: bg, bold: true}}}
	t.printSpans(x+3, y+3, line1, x+mid-1)
	t.printSpans(x+3, y+4, line2, x+mid-1)
}
