func (t *TUI) deviceHeaderSpans() []span {
	white := Style{fg: cWhite}
	def := Style{}
	return []span{{"Device name", white}, {" ", def}, {" Size", white}, {"     ", def}, {" Used", white}, {"     ", def},
		{" Used part", white}, {"   ", def}, {" Free", white}, {"     ", def}, {" Mount point", white}}
}

func (t *TUI) deviceRowSpans(d *Device) []span {
	white := Style{fg: cWhite}
	whiteB := Style{fg: cWhite, bold: true}
	dirSt := Style{fg: t.th.dirColor, bold: true}
	numSt := Style{fg: cYellow, bold: true}
	if !t.th.useColors {
		numSt = whiteB
	}
	used := d.Size - d.Free
	part := 0
	if d.Size > 0 {
		part = int(float64(used) / float64(d.Size) * 100)
	}
	un, uu := sizeParts(used, t.flags.UseSIPrefix, false, false)
	usedStr := un + " " + uu
	pad := ""
	if len(usedStr) < 9 {
		pad = strings.Repeat(" ", 9-len(usedStr))
	}
	return []span{
		{d.Name, dirSt},
		{" " + fmt.Sprintf("%9s", formatSizePlain(d.Size, t.flags.UseSIPrefix, false, false)) + " " + pad, white},
		{un, numSt},
		{" " + uu, whiteB},
		{" " + t.usageBar(part) + " " + fmt.Sprintf("%9s", formatSizePlain(d.Free, t.flags.UseSIPrefix, false, false)) + " ", white},
		{d.MountPoint, dirSt},
	}
}

func (t *TUI) drawDeviceTable(y, h int) {
	if t.selected < 1 {
		t.selected = 1
	}
	visible := h - 1
	if visible < 1 {
		visible = 1
	}
	if t.selected-1 < t.offset {
		t.offset = t.selected - 1
	}
	if t.selected-1-t.offset >= visible {
		t.offset = t.selected - visible
	}
	if t.offset < 0 {
		t.offset = 0
	}
	type rowData struct {
		spans []span
		sel   bool
	}
	rows := []rowData{{t.deviceHeaderSpans(), false}}
	for i := 0; i < visible; i++ {
		idx := t.offset + i
		if idx >= len(t.devices) {
			break
		}
		rows = append(rows, rowData{t.deviceRowSpans(t.devices[idx]), idx+1 == t.selected})
	}
	maxW := 0
	for _, r := range rows {
		if w := spansWidth(r.spans); w > maxW {
			maxW = w
		}
	}
	cellW := maxW + 1
	if cellW > t.term.w {
		cellW = t.term.w
	}
	for i, r := range rows {
		ry := y + i
		if r.sel {
			st := Style{fg: t.th.selFg, bg: t.th.selBg, bold: true}
			t.term.Fill(0, ry, cellW, 1, st)
			t.term.Print(0, ry, spansText(r.spans), st, cellW)
			continue
		}
		t.printSpans(0, ry, r.spans, t.term.w)
	}
}

