	return n
}

// updateStats recomputes sizes, item counts, mtimes and flags of directories,
// counting hard linked files only once. Subdirectories are visited in the order
// they would typically finish scanning (smaller trees first).
func updateStats(dir *Item, linked map[uint64]bool) {
	countItems(dir)
	updateStatsOrdered(dir, linked)
}

func updateStatsOrdered(dir *Item, linked map[uint64]bool) {
	dir.Size = dirOwnSize
	dir.Usage = dirOwnSize
	dir.ItemCount = 1
	if !dir.ownMtime.IsZero() {
		dir.Mtime = dir.ownMtime
	}
	if dir.Flag == '.' {
		dir.Flag = ' '
	}
	order := make([]*Item, 0, len(dir.Files))
	var dirs []*Item
	for _, f := range dir.Files {
		if f.IsDir {
			dirs = append(dirs, f)
		} else {
			order = append(order, f)
		}
	}
	sort.SliceStable(dirs, func(i, j int) bool { return dirs[i].ItemCount < dirs[j].ItemCount })
	order = append(order, dirs...)
	for _, f := range order {
		if f.IsDir {
			updateStatsOrdered(f, linked)
			if (f.Flag == '!' || f.Flag == '.') && dir.Flag != '!' {
				dir.Flag = '.'
			}
		}
		if f.Mli != 0 {
			if linked[f.Mli] {
				dir.ItemCount += f.countValue()
				if f.Mtime.After(dir.Mtime) {
					dir.Mtime = f.Mtime
				}
				continue
			}
			linked[f.Mli] = true
		}
		dir.Size += f.Size
		dir.Usage += f.Usage
		dir.ItemCount += f.countValue()
		if f.Mtime.After(dir.Mtime) {
			dir.Mtime = f.Mtime
		}
	}
}

