func isDigitByte(c byte) bool { return c >= '0' && c <= '9' }

// naturalLess compares strings so that embedded numbers are ordered numerically.
func naturalLess(a, b string) bool {
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		ca, cb := a[i], b[j]
		if isDigitByte(ca) && isDigitByte(cb) {
			ei := i
			for ei < len(a) && isDigitByte(a[ei]) {
				ei++
			}
			ej := j
			for ej < len(b) && isDigitByte(b[ej]) {
				ej++
			}
			ta := strings.TrimLeft(a[i:ei], "0")
			tb := strings.TrimLeft(b[j:ej], "0")
			if len(ta) != len(tb) {
				return len(ta) < len(tb)
			}
			if ta != tb {
				return ta < tb
			}
			i, j = ei, ej
			continue
		}
		if ca != cb {
			return ca < cb
		}
		i++
		j++
	}
	if a == b {
		return false
	}
	return a < b
}
