func importJSON(r io.Reader) (*Item, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	var v interface{}
	if err := json.Unmarshal(data, &v); err != nil {
		return nil, err
	}
	top, ok := v.([]interface{})
	if !ok {
		return nil, fmt.Errorf("JSON file does not contain top level array")
	}
	if len(top) < 4 {
		return nil, fmt.Errorf("top level array must have at least 4 items")
	}
	rootArr, ok := top[3].([]interface{})
	if !ok {
		return nil, fmt.Errorf("array of maps not found in the top level array on 4th position")
	}
	root, err := importDir(rootArr, nil)
	if err != nil {
		return nil, err
	}
	full := root.Name
	root.BasePath = filepath.Dir(full)
	root.Name = filepath.Base(full)
	if full == "/" {
		root.Name = "/"
		root.BasePath = ""
	}
	return root, nil
}

func jsonInt(v interface{}) int64 {
	if f, ok := v.(float64); ok {
		return int64(f)
	}
	return 0
}

func importDir(arr []interface{}, parent *Item) (*Item, error) {
	info, ok := arr[0].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("directory item is not a map")
	}
	name, ok := info["name"].(string)
	if !ok {
		return nil, fmt.Errorf("directory name is not a string")
	}
	dir := &Item{Flag: ' ', IsDir: true, Size: dirOwnSize, Usage: dirOwnSize, Parent: parent, Name: name}
	if mt, ok := info["mtime"]; ok {
		dir.ownMtime = time.Unix(jsonInt(mt), 0)
		dir.Mtime = dir.ownMtime
	}
	for _, c := range arr[1:] {
		switch v := c.(type) {
		case map[string]interface{}:
			f := &Item{Flag: ' ', Parent: dir}
			f.Name = v["name"].(string)
			f.Size = jsonInt(v["asize"])
			f.Usage = jsonInt(v["dsize"])
			if mt, ok := v["mtime"]; ok {
				f.Mtime = time.Unix(jsonInt(mt), 0)
			}
			if ino := jsonInt(v["ino"]); ino != 0 {
				f.Mli = uint64(ino)
				f.Flag = 'H'
			}
			if _, ok := v["hlnkc"]; ok {
				f.Flag = 'H'
			}
			if _, ok := v["notreg"]; ok {
				f.Flag = '@'
			}
			dir.Files = append(dir.Files, f)
		case []interface{}:
			sub, err := importDir(v, dir)
			if err != nil {
				return nil, err
			}
			dir.Files = append(dir.Files, sub)
		}
	}
	return dir, nil
}

